/** 單一速度檔（一般/快/急速）的初始盤面落定 + 消除補格掉落節奏 */
import { Logger } from '../utils/Logger';
export interface ReelTimingTier {
    /** 初始盤面落定：清除舊盤面時長（秒）——GameMain.cascadeTiming() 每次 spin 結果揭曉前讀取套用，
     *  對應 CascadeReelsTask.runTumbleSwap() 呼叫的 ReelView.tumbleClear() */
    tumbleClear: number;
    /** 初始盤面落定：symbol 從上方掉落到定位的時長（秒）——同上，對應 ReelView.tumbleFill() */
    tumbleFill: number;
    /** 清除舊盤面 tween 的 easing 名稱——同上，對應 cc.TweenEasing */
    tumbleClearEase: string;
    /** 落下到位 tween 的 easing 名稱——同上，對應 cc.TweenEasing */
    tumbleFillEase: string;
    /** 消除動畫時長（秒）——GameMain.cascadeTiming() 每次消除補格前讀取套用；0 表示依 Erase spine 的動畫原長 */
    explode: number;
    /** 中獎符號發光/框起來動畫時長（秒）——同上，消除爆炸前先播的 symbol_win 演出，
     *  對應 ReelView.playWinFx()，透過 timeScale 縮放 Spine 播放速度 */
    winFx: number;
    /** 補格掉落耗時基準（秒）——同上 */
    fill: number;
    /** 補格掉落每欄堆疊延遲（秒）——同上 */
    fillStagger: number;
    /** 補格掉落 tween 的 easing 名稱（例如 "quadIn"）——同上，對應 cc.TweenEasing */
    fillEase: string;
}

const TIER_NUMBER_KEYS: (keyof ReelTimingTier)[] = ['tumbleClear', 'tumbleFill', 'explode', 'winFx', 'fill', 'fillStagger'];
const TIER_STRING_KEYS: (keyof ReelTimingTier)[] = ['tumbleClearEase', 'tumbleFillEase', 'fillEase'];

function isValidTier(value: unknown): value is ReelTimingTier {
    if (!value || typeof value !== 'object') return false;
    const tier = value as Record<string, unknown>;
    return TIER_NUMBER_KEYS.every((key) => typeof tier[key] === 'number') && TIER_STRING_KEYS.every((key) => typeof tier[key] === 'string');
}

export interface ReelTimingOverride {
    /** 開始加速階段時長（秒）——SlotGameMain.onNormalSpin() 每次 spin 開始前讀取套用 */
    beginDuration: number;
    /** 等速轉動每格時長（秒）——同上 */
    loopTime: number;
    /** 結束減速階段時長（秒）——同上 */
    endDuration: number;
    /** 開始加速階段的緩動名稱（例如 "linear"）——同上，對應 cc.TweenEasing，
     *  這裡刻意不 import cc 保持這份 store 跟引擎解耦，消費端自己轉型別 */
    beginEase: string;
    /** 結束減速階段的緩動名稱——同上 */
    endEase: string;
    /** 一般節奏的初始盤面落定 + 消除補格掉落節奏；快轉/急速轉不再各自寫死一組節奏，
     *  改由「整體速度」倍率（SceneSpeedStore／DirectorSpeedHook）等比縮放 */
    tier: ReelTimingTier;
}

/**
 * ReelTimingDebugStore
 *
 * PM 透過 DebugPanel 線上調整的轉輪節奏（開始加速／等速轉動／結束減速／開始結束緩動，不分速度檔）、
 * 以及一般節奏的初始盤面落定節奏（清除舊盤面／掉落到位）跟消除補格掉落節奏
 * （消除／掉落／堆疊延遲／掉落緩動），共用同一份 reelConfig.json / 同一個 store，不同消費端各自挑
 * 自己要的欄位：SlotGameMain.onNormalSpin() 只用 beginDuration/loopTime/endDuration/beginEase/endEase
 *（這組對應經典連續滾動轉輪的狀態機，這個遊戲的落球式盤面實際上沒有走完整輪，玩家看不太出效果）；
 * GameMain.cascadeTiming() 固定套用 tier 裡的
 * tumbleClear/tumbleFill（初始盤面，玩家真正會看到的「開始→落下→停止」節奏）跟
 * explode/fill/fillStagger/fillEase（消除後補格）；快轉/急速轉改由整體速度倍率縮放。存取分兩層：
 * - localStorage：PM 在瀏覽器裡調整的即時覆寫值，DebugPanel 負責寫
 * - localDefault：各遊戲自己 jsons/reelConfig.json 載入後餵進來的「本地端預設值」，
 *   GameMain_1001/1002 在 gameInit() 時非同步載入後呼叫 setLocalDefault() 設定
 *
 * get() 的讀取優先序：localStorage 覆寫值 > reelConfig.json 本地端預設值 > null
 *（回傳 null 時交給呼叫端自己的 fallback，沿用 Editor/cascadeTiming() 原本的基準值）。
 * 兩邊消費端都是「每次真的要用之前」才呼叫 get()——避免拖動滑桿當下直接改掉正在播放
 * 中的動畫。1001/1002 共用同一份存取邏輯，用 gameId（例如 "1001"/"1002"）分開儲存。
 */
export default class ReelTimingDebugStore {
    private static readonly localDefaults = new Map<string, ReelTimingOverride>();

    /**
     * 組出這款遊戲在 localStorage 的鍵名。
     *
     * @param gameId 遊戲代號。
     * @returns 鍵名。
     */
    private static storageKey(gameId: string): string {
        return `slot_reel_timing_${gameId}`;
    }

    /** 遊戲啟動時讀完 jsons/reelConfig.json 後呼叫，設定「本地端預設值」這一層（不會覆蓋 PM 已存的 localStorage 覆寫值） */
    public static setLocalDefault(gameId: string, value: ReelTimingOverride): void {
        ReelTimingDebugStore.localDefaults.set(gameId, value);
    }

    /** 只拿「本地端預設值」（reelConfig.json 載入後的內容），不看 localStorage 覆寫值——
     *  DebugPanel 用這個當「恢復預設」的目標，讓預設值永遠反映目前的 reelConfig.json，不用手動同步兩份。 */
    public static getLocalDefault(gameId: string): ReelTimingOverride | null {
        return ReelTimingDebugStore.localDefaults.get(gameId) ?? null;
    }

    /**
     * 取得實際生效的轉輪節奏：localStorage 的覆寫值優先，沒有才用本地預設。
     *
     * @param gameId 遊戲代號。
     * @returns 節奏設定；兩者都沒有時是 null。
     */
    public static get(gameId: string): ReelTimingOverride | null {
        const override = ReelTimingDebugStore.getStoredOverride(gameId);
        if (override) return override;
        return ReelTimingDebugStore.localDefaults.get(gameId) ?? null;
    }

    /**
     * 從 localStorage 讀出覆寫值。讀取或解析失敗只印 warn 回 null，退回本地預設。
     *
     * @param gameId 遊戲代號。
     * @returns 覆寫值；沒有或壞掉時是 null。
     */
    private static getStoredOverride(gameId: string): ReelTimingOverride | null {
        if (typeof localStorage === 'undefined') return null;
        try {
            const raw = localStorage.getItem(ReelTimingDebugStore.storageKey(gameId));
            if (!raw) return null;
            const parsed = JSON.parse(raw);
            const numberKeys: (keyof ReelTimingOverride)[] = ['beginDuration', 'loopTime', 'endDuration'];
            const stringKeys: (keyof ReelTimingOverride)[] = ['beginEase', 'endEase'];
            const tier = parsed?.tier;
            if (numberKeys.every((key) => typeof parsed[key] === 'number') && stringKeys.every((key) => typeof parsed[key] === 'string') && isValidTier(tier)) {
                return {
                    beginDuration: parsed.beginDuration,
                    loopTime: parsed.loopTime,
                    endDuration: parsed.endDuration,
                    beginEase: parsed.beginEase,
                    endEase: parsed.endEase,
                    tier,
                };
            }
        } catch (e) {
            console.warn('[ReelTimingDebugStore] 讀取失敗', Logger.fmt(e));
        }
        return null;
    }

    /**
     * 把覆寫值寫進 localStorage 並通知訂閱者。沒有 localStorage 的環境直接略過。
     *
     * @param gameId 遊戲代號。
     * @param value 節奏設定。
     */
    public static set(gameId: string, value: ReelTimingOverride): void {
        if (typeof localStorage === 'undefined') return;
        try {
            localStorage.setItem(ReelTimingDebugStore.storageKey(gameId), JSON.stringify(value));
        } catch (e) {
            console.warn('[ReelTimingDebugStore] 寫入失敗', Logger.fmt(e));
        }
    }

    /**
     * 清掉 localStorage 的覆寫值（退回本地預設）。
     *
     * @param gameId 遊戲代號。
     */
    public static clear(gameId: string): void {
        if (typeof localStorage === 'undefined') return;
        localStorage.removeItem(ReelTimingDebugStore.storageKey(gameId));
    }
}
