import { JsonAsset, sys } from 'cc';
import { TemplateView } from './TemplateView';
import TemplateModel from './TemplateModel';
import StoreManager from '../../store/StoreManager';
import SpinStartStatus from './SpinStartStatus';
import StatusManager from './StatusManager';
import NewGameStatus from './NewGameStatus';
import { GAMESTOREMAP, AUTOSPINSTATUSMAP, TURBOSTATUSMAP } from '../../store/StoreMap';
import AppAudio, { bindAudioVolumeEvents } from '../../audio/AppAudio';
import { EFFECTSMAP } from '../../audio/SOUNDMAP';
import ReSpinStatus from './ReSpinStatus';
import GameStore from '../../store/SlotGameStore';
import GameEndStatus from './GameEndStatus';
import EagleTracker from '../../tracking/EagleTracker';
import TrackerMap from '../../tracking/TrackerMap';
import AppAssetBundle from '../../utils/AppAssetBundle';
import AppUtility from '../../utils/AppUtility';
import GameConfigManager from '../../config/GameConfigManager';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../../events/GameRuntimeEventBus';
import { GameStateKey } from '../../states/GameStateKey';
import { getSubGameData } from '../../types/SubGameData';

// 選單（含裡面的離開確認與回選桌）／自動旋轉選擇彈窗改由大廳共用，子遊戲不再自帶。
// 這些函式由大廳常駐節點在子遊戲載入前掛上 globalThis，詳見 entry 的 assets/base/subgame/SubGame.ts。
// 獨立 Preview 時不會有人掛，所以每個呼叫點都要先檢查存在才呼叫。
type SubGameGlobalScope = typeof globalThis & {
    __subGameExit__?: () => void;
    __subGameReselectTable__?: () => void;
    __subGameShowSystemMenu__?: () => Promise<void>;
    __subGameShowAutoPlaySelector__?: () => Promise<number | null>;
};

export default class TemplateViewModel {
    /**
     * Turbo 狀態存進 UserDefault 時用的 key。
     *
     * 帶 GAMEID 前綴，避免不同子遊戲互相蓋掉彼此的偏好；GAMEID 是進場景才寫入的，
     * 所以做成 getter 而不是 module-level const（見 docs/agent-pitfalls.md #30）。
     *
     * @returns 形如 `1003_turbo_status` 的 key。
     */
    private get turboKey(): string {
        return `${GameConfigManager.GAMEID.toLowerCase()}_turbo_status`;
    }
    templateView: TemplateView;
    templateStore: TemplateModel;
    storeManager: StoreManager;

    statusManager: StatusManager;
    spinStartStatus: SpinStartStatus;
    newGameStatus: NewGameStatus;
    reSpinStatus: ReSpinStatus;
    gameEndStatus: GameEndStatus;
    gameStore: GameStore;
    kyAudio: AppAudio;

    eagleTracker: EagleTracker;

    assetBundle: AppAssetBundle;
    _orientation: string;

    /**
     * 建立 ViewModel 並綁定它服務的 View。
     *
     * 只取初始方向，其餘初始化都在 initial()；建構當下 View 的節點樹還不保證完整。
     *
     * @param context 這個 ViewModel 對應的 TemplateView。
     */
    constructor(context: TemplateView) {
        this.templateView = context;
        this._orientation = StoreManager.getInstance().getDeviceStore().orientation || 'portrait';
    }
    /**
     * 依序啟動各子系統。
     *
     * 順序有相依：assetBundle 要先建立，setVersionLabel()、turboStatusChange() 都靠它載資產；
     * registerStore() 要早於 initUserDefaultData()，後者會寫入 gameStore。
     */
    initial() {
        this.assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        this.setVersionLabel();
        this.initStatus();
        this.registerStore();
        this.registerReactions();
        this.initAudio();
        this.initGameTracker();
        this.initUserDefaultData();
    }
    /**
     * 更新左下角版號。優先用大廳帶過來的 SubGameData 版本，
     * 其次讀 bundle 內的 version.json。
     *
     * @returns 版號寫入完成的 Promise，讀取失敗只印 warn 不拋。
     */
    private async setVersionLabel(): Promise<void> {
        try {
            const subGameData = getSubGameData();
            if (subGameData?.version) {
                this.templateView.setVersionLabel(subGameData.version);
                return;
            }
            const asset = await this.assetBundle.loadAsset('version', JsonAsset);
            if (!this.templateView?.node?.isValid) return;
            // web 與 native 各自計號 取當前平台那一條
            this.templateView.setVersionLabel(sys.isNative ? asset.json.native : asset.json.web);
        } catch (err) {
            console.warn('[TemplateViewModel] version.json 讀取失敗', err);
        }
    }
    /**
     * 初始化音效引擎、預載常用音效，並綁定音量事件。
     */
    initAudio() {
        this.kyAudio = AppAudio.getInstance(GameConfigManager.GAMEID);
        this.kyAudio.initAudio(this.templateView.node);
        this.kyAudio.preloadAll(Object.values(EFFECTSMAP));
        bindAudioVolumeEvents(GameConfigManager.GAMEID);
    }
    /**
     * 建立四種轉輪狀態物件，並把 View 當成 context 注入。
     *
     * 實際的狀態切換由 statusChange() 交給 StatusManager 執行。
     */
    initStatus() {
        this.statusManager = new StatusManager();
        this.spinStartStatus = new SpinStartStatus().setContext(this.templateView);
        this.newGameStatus = new NewGameStatus().setContext(this.templateView);
        this.reSpinStatus = new ReSpinStatus().setContext(this.templateView);
        this.gameEndStatus = new GameEndStatus().setContext(this.templateView);
    }
    /**
     * 還原玩家上次選的 Turbo 檔位。
     *
     * 沒存過就維持 store 的預設值，不寫入。
     */
    initUserDefaultData() {
        let turboStatus = AppUtility.getUserDefaultData(this.turboKey);
        if (turboStatus) this.gameStore.setTurboStatus(turboStatus);
    }
    /**
     * 取得 StoreManager 並註冊／取回本畫面用的 TemplateModel 與 GameStore。
     */
    registerStore() {
        this.storeManager = StoreManager.getInstance();
        this.templateStore = this.storeManager.getModel('TemplateStore') || new TemplateModel({});
        this.storeManager.registerModel(this.templateStore);
        this.gameStore = this.storeManager.getGameStore();
    }
    /**
     * 訂閱 gameRuntimeEventBus 上所有會影響本畫面的事件。
     *
     * 原本用 mobx reaction，改成事件匯流排後，原先 `fireImmediately: true` 的那幾條
     * 要在訂閱後手動補呼叫一次，才等效於舊行為——每一處都標了註解。
     */
    registerReactions() {
        // mobx 移除計劃：UserStore.balance 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.USER_BALANCE_CHANGED, (e) => this.templateView.updateUserBalance(e.balance));
        this.templateView.updateUserBalance(this.storeManager.getUserStore()?.balance); // 等效原本的 fireImmediately: true

        // mobx 移除計劃：DeviceStore.orientation 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, (e) => this.orientation(e.orientation));
        // 原本 fireImmediately: false，這裡不用手動呼叫一次

        // mobx 移除計劃：TemplateStore.winBalance/betBalance 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.WIN_BALANCE_CHANGED, (e) => this.templateView.updateWinBalance(e.winBalance));
        this.templateView.updateWinBalance(this.templateStore.winBalance); // 等效原本的 fireImmediately: true
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.BET_BALANCE_CHANGED, (e) => this.updateBetBalance(e.betBalance));
        this.updateBetBalance(this.templateStore.betBalance); // 等效原本的 fireImmediately: true

        // mobx 移除計劃：SlotGameStore 欄位已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.SPIN_STATUS_CHANGED, (e) => this.statusChange(e.status));
        this.statusChange(this.storeManager.getGameStore()?.spinStatus); // 等效原本的 fireImmediately: true

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.TURBO_STATUS_CHANGED, (e) => this.turboStatusChange(e.turboStatus));
        this.turboStatusChange(this.storeManager.getGameStore()?.turboStatus); // 等效原本的 fireImmediately: true

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.AUTO_SPIN_TIMES_CHANGED, (e) => this.setSpinTimes(e.autoSpinTimes));
        this.setSpinTimes(this.storeManager.getGameStore()?.autoSpinTimes); // 等效原本的 fireImmediately: true

        // FG 局數倒數
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.FG_ROUND_CHANGED, (e) => {
            this.templateView.updateFgRound?.(e.remaining, e.total, e.awarded);
        });

        // 進出 FG
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_MODE_CHANGED, (e) => {
            this.templateView.setGameMode?.(e.gameMode);
        });
        this.templateView.setGameMode?.(this.gameStore.gameMode);

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_INIT_DATA_CHANGED, (e) => this.initCurrency(e.gameInitData));
        this.initCurrency(this.storeManager.getGameStore()?.gameInitData); // 等效原本的 fireImmediately: true

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.IS_LOCK_CHANGED, (e) => this.setLockStatus(e.isLock));
        this.setLockStatus(this.storeManager.getGameStore()?.isLock); // 等效原本的 fireImmediately: true

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.AUTO_SPIN_STATUS_CHANGED, (e) => this.autoSpinStatusChange(e.autoSpinStatus));
        this.autoSpinStatusChange(this.storeManager.getGameStore()?.autoSpinStatus); // 等效原本的 fireImmediately: true

        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.CASHIER_URL_CHANGED, (e) => this.initStoreBtn(e.cashierURL));
        this.initStoreBtn(this.storeManager.getGameStore()?.cashierURL); // 等效原本的 fireImmediately: true

        // mobx 移除計劃：TrackerStore.groupType 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.templateView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GROUP_TYPE_CHANGED, (e) => this.updateUserGroup(e.groupType));
        this.updateUserGroup(this.storeManager.getTrackerStore().groupType); // 等效原本的 fireImmediately: true
    }
    /**
     * 依玩家分組調整 Turbo 預設檔位。
     *
     * 目前整段停用，實際上是 no-op——依分組自動套 Turbo 檔位的規則還沒定案，
     * 先讓玩家自己選。原本依 GROUPTYPE.A／B 套 NORMAL／MAX 的寫法留在 git 歷史裡。
     *
     * @param groupType TrackerStore 的分組代碼，falsy 時直接略過。
     */
    updateUserGroup(groupType) {
        if (!groupType) return;
    }
    /**
     * 依開局資料設定幣別顯示。
     *
     * 目前是保留的掛勾點，1001／1002 也是同樣的空實作，三款同名以維持一致。
     *
     * @param initData GameStore 的開局資料，falsy 時直接略過。
     * @returns 無實際非同步工作，僅維持與呼叫端一致的簽章。
     */
    async initCurrency(initData) {
        if (!initData) return;
    }
    /**
     * 取得埋點單例並綁定到本畫面。
     */
    initGameTracker() {
        this.eagleTracker = EagleTracker.getInstance();
        this.eagleTracker.initGameTracker(this.templateView);
    }

    /**
     * 依有無金流網址決定商店按鈕的顯示。
     *
     * @param cashierURL 後端給的金流網址，沒有就把按鈕隱藏。
     */
    initStoreBtn(cashierURL) {
        if (!cashierURL) {
            this.templateView.shopBtn.active = false;
            return;
        }
        this.templateView.shopBtn.active = true;
    }
    /**
     * 更新自動旋轉的剩餘局數顯示。
     *
     * @param spinTimes 剩餘局數，或 `MAX` 代表無限。
     */
    setSpinTimes(spinTimes) {
        this.templateView.updateAutoSpinTimes(spinTimes);
    }

    /**
     * 更新押注額顯示，並依是否已到上下限決定加減號按鈕要不要反灰。
     *
     * @param balance 目前押注額，會跟 templateStore.betLeavel 的頭尾比對。
     */
    updateBetBalance(balance) {
        let betLevel = this.templateStore.betLeavel;
        if (balance === betLevel[betLevel.length - 1]) {
            this.templateView.setAddBtnStatus(true);
            this.templateView.setMinusBtnStatus(false);
        } else if (balance === betLevel[0]) {
            this.templateView.setAddBtnStatus(false);
            this.templateView.setMinusBtnStatus(true);
        } else {
            this.templateView.setAddBtnStatus(false);
            this.templateView.setMinusBtnStatus(false);
        }
        this.templateView.updateBetBalance(balance);
    }

    /**
     * 記錄目前螢幕方向，供彈窗選擇對應的橫／直式版型。
     *
     * @param orientation `portrait` 或 `landscape`。
     */
    orientation(orientation) {
        this._orientation = orientation;
    }

    /**
     * 旋轉未完全停止 spin 以外的按鈕都應該擋掉
     */
    /**
     * 旋轉未完全停止時，spin 以外的按鈕都應該擋掉。
     *
     * @returns 轉輪是否還在進行中。
     */
    private isSpinInProgress(): boolean {
        return this.gameStore.spinStatus !== GAMESTOREMAP.NEW_GAME;
    }

    // ******************** View Click Event  ************************
    /**
     * Spin 按鈕。依當下狀態分別代表「開始新局」「停止自動旋轉」或「提前停輪」。
     *
     * 免費遊戲是固定表演，不接受停輪。
     *
     * @returns 狀態寫入 gameStore 後即結束，實際轉輪由狀態機驅動。
     */
    async spinClick() {
        // FG 是固定表演 不能 Spin 停止
        if (this.gameStore.gameMode === GameStateKey.FG) return;
        // AutoSpin 中按 Spin 代表停止後續局數
        if (this.gameStore.autoSpinStatus === AUTOSPINSTATUSMAP.ON) {
            this.gameStore.setAutoSpinStatus(AUTOSPINSTATUSMAP.OFF);
            return;
        }
        if (this.gameStore.spinStatus === GAMESTOREMAP.NEW_GAME) {
            this.kyAudio.playEffect(EFFECTSMAP.SPIN_CLICK);
            if (!this.gameStore.spinCheck()) return;
            this.gameStore.setSpinStatus(GAMESTOREMAP.SPIN_START);
        } else {
            this.gameStore.setSpinStatus(GAMESTOREMAP.SPIN_END);
        }
    }
    /**
     * 選單按鈕。選單本體由大廳共用，透過 globalThis 橋接呼叫。
     *
     * 獨立 Preview 時大廳沒掛上橋接，所以呼叫前一定要檢查存在。
     *
     * @returns 大廳選單關閉後 resolve；沒有橋接時立即返回。
     */
    async menuClick() {
        if (this.isSpinInProgress()) return;
        this.kyAudio.playEffect(EFFECTSMAP.MENU_CLICK);
        const scope = globalThis as SubGameGlobalScope;
        if (!scope.__subGameShowSystemMenu__) {
            console.warn('[TemplateViewModel] showSystemMenu 未接上大廳 Bridge，獨立測試模式略過');
            return;
        }
        await scope.__subGameShowSystemMenu__();
    }
    /**
     * 自動旋轉按鈕。關閉中按下＝開啟設定彈窗，開啟中按下＝停止後續局數。
     *
     * 彈窗同樣由大廳共用，獨立 Preview 時略過。prefab 的 clickEvents 以字串綁定此函式名，
     * 改名必須連 TemplateViewH/V.prefab 一起改（見 docs/agent-pitfalls.md #16）。
     * entry 那份 1003 與 0000 基底仍是舊拼法 autoCLick，兩邊各自自洽、不共用。
     *
     * @returns 玩家關閉彈窗並寫入局數後 resolve。
     */
    async autoClick() {
        if (this.gameStore.gameMode === GameStateKey.FG) return;
        this.kyAudio.playEffect(EFFECTSMAP.AUTO_SPIN_CLICK);
        if (this.gameStore.autoSpinStatus === AUTOSPINSTATUSMAP.OFF) {
            // 開自動旋轉設定視窗要擋
            if (this.isSpinInProgress()) return;
            const scope = globalThis as SubGameGlobalScope;
            if (!scope.__subGameShowAutoPlaySelector__) {
                console.warn('[TemplateViewModel] showAutoPlaySelector 未接上大廳 Bridge，獨立測試模式略過');
                return;
            }
            // 選取即代表 confirm，彈窗選取後會自己關閉；cancel（停止後續局數）不在這裡，
            // 由下方的 else 分支處理（遊戲內 Auto 按鈕再次點擊時觸發）
            const count = await scope.__subGameShowAutoPlaySelector__();
            if (count !== null && count !== undefined) {
                this.gameStore.setAutoSpinTimes(count < 0 ? 'MAX' : count);
                this.gameStore.setAutoSpinStatus(AUTOSPINSTATUSMAP.ON);
            }
        } else {
            // 遊戲內 Auto 按鈕再次點擊＝cancel，停止後續局數
            this.gameStore.setAutoSpinStatus(AUTOSPINSTATUSMAP.OFF);
        }
    }
    /**
     * Turbo 按鈕。在 NORMAL → FAST → MAX → NORMAL 之間輪替，並存進 UserDefault。
     */
    turboClick() {
        if (this.isSpinInProgress()) return;
        this.kyAudio.playEffect(EFFECTSMAP.TURBO_CLICK);
        switch (this.gameStore.turboStatus) {
            case TURBOSTATUSMAP.NORMAL:
                this.gameStore.setTurboStatus(TURBOSTATUSMAP.FAST);
                AppUtility.setUserDefaultData(this.turboKey, TURBOSTATUSMAP.FAST);
                break;
            case TURBOSTATUSMAP.FAST:
                this.gameStore.setTurboStatus(TURBOSTATUSMAP.MAX);
                AppUtility.setUserDefaultData(this.turboKey, TURBOSTATUSMAP.MAX);
                break;
            case TURBOSTATUSMAP.MAX:
                this.gameStore.setTurboStatus(TURBOSTATUSMAP.NORMAL);
                AppUtility.setUserDefaultData(this.turboKey, TURBOSTATUSMAP.NORMAL);
                break;
        }
    }

    /**
     * 降低一檔押注額。轉輪進行中或自動旋轉中都擋掉。
     */
    minusClick() {
        if (this.isSpinInProgress() || this.gameStore.autoSpinStatus === AUTOSPINSTATUSMAP.ON) return;
        this.kyAudio.playEffect(EFFECTSMAP.BET_CHANGE);
        this.templateStore.minusBetLevel();
    }
    /**
     * 提高一檔押注額。轉輪進行中或自動旋轉中都擋掉，並送出加注埋點。
     */
    plusClick() {
        if (this.isSpinInProgress() || this.gameStore.autoSpinStatus === AUTOSPINSTATUSMAP.ON) return;
        this.kyAudio.playEffect(EFFECTSMAP.BET_CHANGE);
        this.templateStore.addBetLevel();
        EagleTracker.trackerEvent(TrackerMap.BET_INCREASE_AT_PEAK, { current_visual_level: StoreManager.getInstance().getTrackerStore().visualBalance });
    }

    /**
     * 開啟押注額選擇彈窗，依目前螢幕方向取對應版型。
     */
    selectBetClick() {
        if (this.isSpinInProgress() || this.gameStore.autoSpinStatus === AUTOSPINSTATUSMAP.ON) return;
        this.storeManager.getViewStore().selectBetView(this._orientation);
    }

    /**
     * 前往金流頁。沒有網址時順手把按鈕隱藏，避免玩家再點一次。
     */
    storeClick() {
        if (this.isSpinInProgress()) return;
        if (!this.gameStore.cashierURL) {
            this.templateView.shopBtn.active = false;
            return;
        }
        window.open(this.gameStore.cashierURL, '_self');
    }

    // ******************** Status ************************
    /**
     * 自動旋轉狀態變更時同步 UI 與轉輪。
     *
     * 收到 ON 時若正停在新局狀態，直接觸發下一次 spin。
     *
     * @param status AUTOSPINSTATUSMAP 的 ON／OFF。
     */
    autoSpinStatusChange(status: string | undefined) {
        switch (status) {
            // 收到 OFF 要把轉動狀態停下來
            case AUTOSPINSTATUSMAP.OFF:
                if (this.gameStore.spinStatus !== GAMESTOREMAP.NEW_GAME) {
                    this.templateView.setSpinStopStatus(true);
                    this.templateView.setAutoSpinStatus(false);
                }
                break;
            // 這個分支讀即時的 store，上面那個讀快取的 this.gameStore——整支檔案兩種取法
            // 混用（26 處快取、9 處即時），切換子遊戲後兩者可能不是同一個物件，見
            // agent-pitfalls.md 坑 #30。尚未統一，改動時要連整支一起決定。
            case AUTOSPINSTATUSMAP.ON: {
                const gameStore = this.storeManager.getGameStore();
                if (gameStore.spinStatus !== GAMESTOREMAP.NEW_GAME) break;
                gameStore.setSpinStatus(GAMESTOREMAP.SPIN_START);
                break;
            }
        }
    }
    /**
     * Turbo 檔位變更時換掉按鈕圖。
     *
     * 圖掛在 turbo 鈕的 BaseButton 型態列表上，型態名稱就是 TURBOSTATUSMAP 的值，
     * 所以這裡只要把檔位原樣轉交即可。型態沒接時 BaseButton 自己會出警告。
     *
     * @param status TURBOSTATUSMAP 的 NORMAL／FAST／MAX；不在表內的值不做事。
     */
    turboStatusChange(status) {
        const view = this.templateView;
        if (!view?.node?.isValid) return;

        switch (status) {
            case TURBOSTATUSMAP.NORMAL:
            case TURBOSTATUSMAP.FAST:
            case TURBOSTATUSMAP.MAX:
                view.setTurboGear(status);
                break;
            default:
        }
    }
    /**
     * 轉輪狀態變更時，把對應的狀態物件交給 StatusManager。
     *
     * @param status GAMESTOREMAP 的狀態代碼，未列出的值不做事。
     */
    statusChange(status) {
        switch (status) {
            case GAMESTOREMAP.NEW_GAME:
                this.statusManager.spinStatusChange(this.newGameStatus);
                break;
            case GAMESTOREMAP.SPIN_START:
                this.statusManager.spinStatusChange(this.spinStartStatus);
                break;
            case GAMESTOREMAP.RESPIN:
                this.statusManager.spinStatusChange(this.reSpinStatus);
                break;
            case GAMESTOREMAP.GAME_END:
                this.statusManager.spinStatusChange(this.gameEndStatus);
                break;
            default:
                break;
        }
    }
    /**
     * 鎖定／解鎖整個操作列。
     *
     * @param islock true 為鎖定。
     */
    setLockStatus(islock) {
        this.templateView.setLockStatus(islock);
    }
}
