import { _decorator, easing, Node, Sprite, SpriteFrame, Tween, tween, type TweenEasing, UIOpacity, Vec3 } from 'cc';
import { EventComponent } from '../../events/EventComponent';
import { ReelModel, ReelState } from '../model/ReelModel';
import { SymbolCell } from '../symbol/SymbolCell';
import { ReelFlag } from '../symbol/SymbolState';

const { ccclass, property } = _decorator;

/** cc.easing 命名空間依字串名稱查函式，找不到就 fallback 到 linear（等同原本沒套用任何緩動） */
function resolveEasing(name: string): (k: number) => number {
    const fn = (easing as unknown as Record<string, ((k: number) => number) | undefined>)[name];
    return fn ?? easing.linear;
}

@ccclass('1003/ReelView')
export class ReelView extends EventComponent {
    @property(Node)
    protected container: Node = null!;

    @property({ type: [Node], tooltip: '停輪格位標記點 由上到下排列 前 2 個(index 0-1)是補牌進場緩衝 中間 5 個(index 2-6)是玩家看得到的可視 5 排 最後 2 個(index 7-8)是消除掉落緩衝 手動擺位時要對齊間距' })
    public posList: Node[] = [];

    @property([SpriteFrame])
    public spriteFrames: SpriteFrame[] = [];

    @property({ tooltip: '開始加速階段的緩動名稱，對應 cc.TweenEasing（例如 quadOut）' })
    protected beginEase: string = 'linear';

    @property({ tooltip: '結束減速階段的緩動名稱，對應 cc.TweenEasing（例如 quadIn）' })
    protected endEase: string = 'linear';

    @property({ tooltip: '開始加速階段時長（秒）' })
    protected beginDuration: number = 0.5;

    @property({ tooltip: '結束減速階段時長（秒）' })
    protected endDuration: number = 0.1;

    @property({ tooltip: '等速轉動時，每移動一格所需時間（秒）' })
    protected loopTime: number = 0.05;

    public model: ReelModel = null!;
    public symbolNodes: Node[] = [];
    protected symbolOpacities: UIOpacity[] = [];
    protected posIndexes: number[] = [];

    public strip: number[] = [];

    protected ratio: number = 0;
    protected time: number = 0;
    protected isSpinning: boolean = false;

    /**
     * 這一欄每個格位上的邏輯格，與 {@link symbolNodes} 同索引。
     *
     * `symbolNodes[i]` 是節點本身（轉動時被搬位置的那顆），`symbolCells[i]` 是掛在它上面、
     * 決定該顯示哪個符號的哪個狀態的元件。由子類在建立格子時填入；基底自己不使用。
     */
    public symbolCells: (SymbolCell | null)[] = [];

    /** 輪軸層級的旗標，影響這一欄所有格子推算出來的預設狀態 */
    private reelFlags: number = ReelFlag.None;

    /**
     * 開關一個輪軸旗標。
     *
     * 這是壓黑不需要逐格設定的原因：中獎演出只要打開 {@link ReelFlag.Black}，沒有被指定強制
     * 狀態的格子就會自己回退成 `Black`（見 `SymbolCell.getTargetState()`）。
     *
     * @param flag 要操作的旗標。
     * @param enable true 開啟、false 關閉。
     */
    public setReelFlag(flag: ReelFlag, enable: boolean): void {
        const next = enable ? this.reelFlags | flag : this.reelFlags & ~flag;
        if (next === this.reelFlags) return;
        this.reelFlags = next;
        for (const cell of this.symbolCells) cell?.markStateDirty();
    }

    /**
     * 查詢輪軸旗標，`ISymbolCellHost` 的實作。
     *
     * @param flag 要查的旗標。
     * @returns 該旗標是否開啟。
     */
    public hasReelFlag(flag: ReelFlag): boolean {
        return (this.reelFlags & flag) !== 0;
    }

    /**
     * 這一欄是否在轉動，`ISymbolCellHost` 的實作。
     *
     * 方法名不叫 `isSpinning` 是因為那是本類別既有的 protected 欄位，同名會衝突。
     *
     * @returns 轉動中為 true。
     */
    public isReelSpinning(): boolean {
        return this.isSpinning;
    }

    /**
     * 覆寫這一欄的轉輪節奏，供 DebugPanel 調參用。
     *
     * @param bd 起轉加速的秒數。
     * @param lt 等速轉動時每跳一格的秒數。
     * @param ed 停輪減速的秒數。
     */
    applySpeed(bd: number, lt: number, ed: number): void {
        this.beginDuration = bd;
        this.loopTime = lt;
        this.endDuration = ed;
    }

    /** 目前的轉輪節奏設定（開始加速／等速轉動／結束減速），供 DebugPanel 之類的外部工具讀取顯示用 */
    getSpeed(): { beginDuration: number; loopTime: number; endDuration: number } {
        return { beginDuration: this.beginDuration, loopTime: this.loopTime, endDuration: this.endDuration };
    }

    /**
     * 覆寫這一欄的起轉與停輪緩動曲線，供 DebugPanel 調參用。
     *
     * @param beginEase 起轉的緩動名稱。
     * @param endEase 停輪的緩動名稱。
     */
    applyEase(beginEase: string, endEase: string): void {
        this.beginEase = beginEase;
        this.endEase = endEase;
    }

    /** 目前的開始/結束緩動名稱，供 DebugPanel 之類的外部工具讀取顯示用 */
    getEase(): { beginEase: string; endEase: string } {
        return { beginEase: this.beginEase, endEase: this.endEase };
    }

    /**
     * 綁定這一欄的 model、建立符號節點，並訂閱 model 的狀態變化。
     *
     * 進 STOPPING 時會先把 currentRng 校正到「終點再往前 posList 長度」的位置，
     * 讓接下來的減速剛好停在 finalRng 上，不必另外做補間。
     *
     * mobx 移除之後 model 的狀態改用自己的 TypedEventBus 通知。
     *
     * @param model 這一欄的轉輪 model。
     * @param iconColumn 這一欄的符號名稱序列；不給就沿用現有的。
     */
    init(model: ReelModel, iconColumn?: string[]): void {
        if (iconColumn) {
            this.strip = this.buildStrip(iconColumn);
        }

        this.model = model;
        this.initSymbols();

        // mobx 移除計劃：ReelModel.state 已改由自己的 TypedEventBus 通知，不再用 mobx reaction
        this.subscribeEvent(this.model.events, 'stateChanged', ({ state }) => {
            if (state === ReelState.IDLE) {
                this.isSpinning = false;
            } else if (state === ReelState.STOPPING) {
                const lastCount = this.posList.length;
                const newRng = (this.model.finalRng + lastCount + this.strip.length) % this.strip.length;
                this.model.setCurrentRng(newRng);
            } else {
                this.time = 0;
                this.isSpinning = true;
            }
        });

        this.subscribeEvent(this.model.events, 'forceSnap', (rng) => this.snapToFinal(rng));
    }

    /** 收到強制快照通知時，把 reel 立即帶到準備停止的位置（設進 END 狀態），依目前狀態分三種處理：
     *  - STOPPING：rapid-step 直接跑到 oneStepBefore，再手動同步 posIndexes 對應的畫面位置
     *  - END：把 time 校正到 70% 進度，讓收尾動畫接著播完
     *  - BEGIN/LOOP：直接設定 currentRng，同步 posIndexes/symbol 顯示到 oneStepBefore */
    public snapToFinal(rng: number): void {
        this.time = 0;
        this.isSpinning = true;
        const oneStepBefore = (((rng + 1) % this.strip.length) + this.strip.length) % this.strip.length;

        if (this.model.state === ReelState.STOPPING) {
            // rapid-step 直接跑迴圈到 oneStepBefore，safety 是防止意外跑成無窮迴圈的安全上限
            let safety = this.strip.length;
            while (this.model.currentRng !== oneStepBefore && safety-- > 0) {
                this.step();
            }
            // step() 不會動到 symbol 實際位置，這裡才手動 snap 到 posList[posIndexes[i]]
            for (let i = 0; i < this.symbolNodes.length; i++) {
                const curIdx = this.posIndexes[i];
                this.symbolNodes[i].setPosition(0, this.posList[curIdx].position.y, 0);
                const op = this.symbolOpacities[i];
                if (op) op.opacity = curIdx === this.posList.length - 1 ? 0 : 255;
            }
            this.updateDrawOrder();
            this.model.setState(ReelState.END);
            return;
        }

        if (this.model.state === ReelState.END) {
            // 已經在 END 狀態，把 time 設到 70% 進度，讓收尾動畫接著播完
            this.time = this.endDuration * 0.7;
            return;
        }

        // BEGIN/LOOP：目前 posIndexes 對應的 position，跟 symbols 實際該顯示的畫面不同步，
        // 所以要用 currentRng 反推每個 symbol 該對應哪個 posIdx 的 strip frame，
        // 讓 updateEnd 之後的 position 插值直接對齊 posList[curIdx]，跳過中間的落差
        this.model.setCurrentRng(oneStepBefore);
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const stripIdx = (oneStepBefore + this.posIndexes[i]) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
        this.model.setState(ReelState.END);
    }

    /**
     * 依 posList 長度建立符號節點，逐一掛上 UIOpacity 並記下初始 posIndex。
     *
     * 節點數量等於 posList 長度而不是可視列數：頭尾各留兩格 buffer，
     * 轉動時符號是循環搬位置而不是生成銷毀。
     */
    /**
     * 建立這一欄的格子。由子類實作。
     *
     * 基底原本的版本是 `instantiate(symbolPrefab)`——每一格複製一份掛滿全部美術的 NgSymbol。
     * 改成物件池之後格子是沒有美術的空殼、要顯示什麼向池子租，那份 prefab 與對應的
     * `symbolPrefab` 欄位已隨 NgSymbol 一起移除，所以這裡只留一個掛勾。
     *
     * 實作要負責把 {@link symbolNodes}／{@link symbolCells}／{@link symbolOpacities}／
     * {@link posIndexes} 四個平行陣列填滿（長度都等於 `posList.length`），最後呼叫
     * {@link updateDrawOrder}；基底其餘的轉動邏輯都靠這幾個陣列運作。
     */
    protected initSymbols(): void {
        console.warn(`[ReelView] ${this.node.name} 沒有覆寫 initSymbols()，這一欄不會有任何格子`);
    }

    /** 依 posIdx 排序調整每個 symbol 的顯示層級（sibling index），
     *  container 底下固定就是這幾個 pos，只是重新排序疊放順序，
     *  確保 posIdx 越大（越下面）的 symbol 疊在越上層，畫面前後關係才正確 */
    protected updateDrawOrder(): void {
        const order = this.symbolNodes.map((_, i) => i).sort((a, b) => this.posIndexes[a] - this.posIndexes[b]);
        const last = this.container.children.length - 1;
        for (const i of order) {
            this.symbolNodes[i].setSiblingIndex(last);
        }
    }

    /** 給子類覆寫：symbol 進入頂部、換上新 frame 時的處理（例如判斷是不是 coin 顯示） */
    protected onSymbolStepIntoTop(_symbolIdx: number, _stripIdx: number, _frameIdx: number): void {}

    /** 給子類覆寫：symbol 下落／消除 settle 完成後的收尾處理 */
    protected onSymbolSettled(_symbolIdx: number): void {}

    /** 給子類覆寫：API 符號名稱 → spriteFrame 名稱的對照表 */
    protected getSymbolNameMap(): Record<string, string> {
        return {};
    }

    /** 這一欄實際可視列數（posList 扣掉頭部 2 列進場 buffer 與尾部 2 列掉落 buffer），不規則輪帶每欄可能不同 */
    get visibleRowCount(): number {
        return Math.max(0, this.posList.length - 4);
    }

    /**
     * 可視列 row 對應到 posList 的索引偏移。
     *
     * 預設 2，也就是頭部那兩格進場 buffer——可視列 0 就是 posList 的第 3 格。
     * 子類別如果在可視區裡安插了不吃後端資料的裝飾格（1003 葫蘆型盤面兩側欄的上下半格），
     * 要覆寫這個值把那些格子讓開，否則後端的列會整欄錯位。
     */
    protected get rowToPosOffset(): number {
        return 2;
    }

    /**
     * 這一欄真正吃後端資料的列數。
     *
     * 預設等於可視列數。子類別若在可視區裡安插裝飾格，要覆寫成扣掉那些格子之後的數字。
     */
    protected get dataRowCount(): number {
        return this.visibleRowCount;
    }

    /**
     * 取得可視區某一列目前顯示的符號節點。
     *
     * @param row 可視列索引（0 起算，會自動跳過頭部 2 格 buffer）。
     * @returns 該列的節點；沒有節點停在那個位置時是 null。
     */
    getVisibleSymbol(row: number): Node | null {
        const posIdx = row + this.rowToPosOffset;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) {
                return this.symbolNodes[i];
            }
        }
        return null;
    }

    /**
     * 找出目前停在指定格位的是哪一個符號節點。
     *
     * @param posIdx posList 的索引。
     * @returns symbolNodes 的索引；沒有節點在那裡時回 -1。
     */
    findSymbolNodeAtPosIndex(posIdx: number): number {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) return i;
        }
        return -1;
    }

    /** 依 spriteFrame 名稱找 frameIdx，找不到回傳 -1（原本 tumbleFill/setInitialSymbol/
     * CascadeReelsTask 各自重寫一份一模一樣的線性搜尋，收斂成這一份共用） */
    frameIdxByName(name: string): number {
        for (let i = 0; i < this.spriteFrames.length; i++) {
            if (this.spriteFrames[i]?.name === name) return i;
        }
        return -1;
    }

    /**
     * 換掉整條輪帶並立刻重繪畫面。
     *
     * @param iconColumn 新的符號名稱序列。
     */
    updateStrip(iconColumn: string[]): void {
        this.strip = this.buildStrip(iconColumn);
        this.refreshDisplay();
    }

    /**
     * 直接指定可視區某一列要顯示哪個符號（不經過輪帶，用於還原盤面）。
     *
     * @param row 可視列索引（0 起算）。
     * @param symbolName 後端的符號名稱，會先過一次名稱對照表。
     */
    setInitialSymbol(row: number, symbolName: string): void {
        const posIdx = row + this.rowToPosOffset;
        const map = this.getSymbolNameMap();
        const imgName = map[symbolName] ?? symbolName;
        const frameIdx = Math.max(0, this.frameIdxByName(imgName));
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) {
                this.setSymbolDisplay(i, frameIdx);
                break;
            }
        }
    }

    /**
     * 依目前的 currentRng 把每個符號節點的圖重繪一次。
     */
    refreshDisplay(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const stripIdx = (this.model.currentRng + i) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
    }

    /**
     * 把後端的符號名稱序列轉成 spriteFrames 的索引序列。
     *
     * 對不到名稱的一律退回索引 0，而不是留 undefined——`spriteFrames[undefined]` 指派給
     * `Sprite.spriteFrame` 不會報錯，只會什麼都不顯示，比顯示錯圖還難查（見 agent-pitfalls.md 坑 #23）。
     *
     * @param iconColumn 後端的符號名稱序列。
     * @returns 對應的 frame 索引序列。
     */
    buildStrip(iconColumn: string[]): number[] {
        const nameToIndex: Record<string, number> = {};
        for (let i = 0; i < this.spriteFrames.length; i++) {
            if (this.spriteFrames[i]) {
                nameToIndex[this.spriteFrames[i].name] = i;
            }
        }
        const map = this.getSymbolNameMap();
        return iconColumn.map((apiName) => {
            const imgName = map[apiName] ?? apiName;
            return nameToIndex[imgName] ?? 0;
        });
    }

    /** 套用 sprite 顯示；需要 spine 特效的子類自己 override */
    setSymbolDisplay(symbolIdx: number, frameIdx: number): void {
        const symbol = this.symbolNodes[symbolIdx];
        const sprite = symbol.getComponent(Sprite);
        if (sprite) {
            sprite.enabled = true;
            sprite.spriteFrame = this.spriteFrames[frameIdx];
        }
    }

    /**
     * 把這一輪的盤面結果寫回輪帶的可視段，讓之後的轉動接得上畫面上的符號。
     *
     * 起點用 {@link rowToPosOffset} 而不是寫死的 2：可視區裡有裝飾格時偏移會變大，
     * 寫錯位置會讓下一輪轉動時整欄的符號對不上。
     *
     * @param frameIdxes 這一輪各可視列的 frameIdx，順序由上而下。
     */
    patchVisibleStrip(frameIdxes: number[]): void {
        for (let i = 0; i < frameIdxes.length; i++) {
            this.strip[this.rowToPosOffset + i] = frameIdxes[i];
        }
    }

    /**
     * 每幀依 model 的狀態推進對應的轉動階段；沒在轉時直接返回。
     *
     * @param dt 距離上一幀的秒數。
     */
    protected override update(dt: number): void {
        if (!this.isSpinning) return;

        this.time += dt;

        switch (this.model.state) {
            case ReelState.BEGIN:
                this.updateBegin();
                break;
            case ReelState.LOOP:
                this.updateLoop();
                break;
            case ReelState.STOPPING:
                this.updateStopping();
                break;
            case ReelState.END:
                this.updateEnd();
                break;
        }
    }

    /**
     * 起轉加速階段：依 beginEase 換算位移比例，跑滿一段就跳一格並轉入等速。
     */
    protected updateBegin(): void {
        const progress = Math.min(this.time / this.beginDuration, 1);
        this.ratio = resolveEasing(this.beginEase)(progress);

        if (progress >= 1) {
            this.step();
            this.time = 0;
            this.model.setState(ReelState.LOOP);
            return;
        }

        this.moveSymbols();
    }

    /**
     * 等速轉動階段：時間跑滿一格就跳一格，餘數留給下一格，避免累積誤差。
     */
    protected updateLoop(): void {
        this.ratio = this.time / this.loopTime;

        if (this.ratio >= 1) {
            this.time = this.time % this.loopTime;
            this.ratio = this.time / this.loopTime;
            this.step();
        }
        this.moveSymbols();
    }

    /**
     * 準備停輪階段：維持等速，但每跳一格就檢查是否已經到達停輪位置。
     */
    protected updateStopping(): void {
        this.ratio = this.time / this.loopTime;

        if (this.ratio >= 1) {
            this.time = this.time % this.loopTime;
            this.ratio = this.time / this.loopTime;
            this.step();

            const oneStepBefore = (((this.model.finalRng + 1) % this.strip.length) + this.strip.length) % this.strip.length;
            if (this.model.currentRng === oneStepBefore) {
                this.model.setState(ReelState.END);
                return;
            }
        }
        this.moveSymbols();
    }

    /**
     * 停輪減速階段：跑完後跳最後一格、對齊到精確位置，並通知 model 已停止。
     */
    protected updateEnd(): void {
        const progress = Math.min(this.time / this.endDuration, 1);

        if (progress >= 1) {
            this.step();
            this.snapToFinalPosition();
            this.model.onStopped();
            return;
        }

        this.ratio = resolveEasing(this.endEase)(progress);
        this.moveSymbols();
    }

    /**
     * 把所有符號節點直接對齊到各自 posIndex 的座標，消掉插值留下的零頭。
     */
    protected snapToFinalPosition(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const curIdx = this.posIndexes[i];
            const y = this.posList[curIdx].position.y;
            this.symbolNodes[i].setPosition(0, y, 0);
        }
    }

    /**
     * 把每個符號往前推一格，並同步倒推 model 的 currentRng。
     *
     * 只改邏輯上的格位索引，**不動節點實際座標**——座標由 moveSymbols() 每幀插值，
     * 或由 snapToFinalPosition() 一次對齊。
     */
    protected step(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            this.posIndexes[i] = (this.posIndexes[i] + 1) % this.posList.length;
        }

        const newRng = (this.model.currentRng - 1 + this.strip.length) % this.strip.length;
        this.model.setCurrentRng(newRng);

        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === 0) {
                const stripIdx = this.model.currentRng;
                const frameIdx = this.strip[stripIdx];
                this.setSymbolDisplay(i, frameIdx);
                this.onSymbolStepIntoTop(i, stripIdx, frameIdx);
            }
        }

        this.updateDrawOrder();
    }

    /**
     * 依目前的位移比例，把每個符號在「目前格位」與「下一格位」之間插值移動，
     * 並處理進出可視區時的淡入淡出。
     */
    protected moveSymbols(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const curIdx = this.posIndexes[i];
            const nextIdx = (curIdx + 1) % this.posList.length;

            const opacity = this.symbolOpacities[i];

            if (curIdx === this.posList.length - 1) {
                opacity.opacity = 0;
            } else {
                opacity.opacity = 255;
            }

            const curY = this.posList[curIdx].position.y;
            const nextY = this.posList[nextIdx].position.y;

            const newY = curY + (nextY - curY) * this.ratio;
            this.symbolNodes[i].setPosition(0, newY, 0);
        }
    }

    // ========== 物理式掉落輔助方法 ==========

    /** 依「參考距離／參考時間」推出重力常數，再算出任意距離的掉落時間（等加速度掉落）。
     *  g = 2 * refDistance / refDuration^2；t = sqrt(2 * distance / g)
     *  沿用既有已調校好的 reference（例：cellHeight/fillTime），讓不同掉落距離有物理上合理的比例，
     *  同時維持 normal/fast/turbo 各速度檔既有的調校手感。 */
    protected physicsFallDuration(distance: number, referenceDistance: number, referenceDuration: number): number {
        const dist = Math.abs(distance);
        const refDist = Math.abs(referenceDistance);
        if (refDist <= 0 || referenceDuration <= 0 || dist <= 0) return referenceDuration;
        const gravity = (2 * refDist) / (referenceDuration * referenceDuration);
        if (gravity <= 0) return referenceDuration;
        return Math.sqrt((2 * dist) / gravity);
    }

    /** 單一 cell 的高度（絕對值），做為物理掉落的參考距離。 */
    protected cellHeightAbs(): number {
        if (this.posList.length < 2) return 0;
        return Math.abs(this.posList[0].position.y - this.posList[1].position.y);
    }

    /** 在既有 tween 鏈後面接上「落地彈跳」：先小幅衝過目標位置，再彈回目標，
     *  讓掉落停下的瞬間多一點重量感，銜接在 scale-squash 關鍵影格之前。 */
    protected appendLandingBounce(t: Tween<Node>, targetY: number, cellHeight: number): Tween<Node> {
        const bounce = Math.max(Math.abs(cellHeight) * 0.05, 2);
        return t.to(0.055, { position: new Vec3(0, targetY - bounce, 0) }, { easing: 'quadOut' }).to(0.07, { position: new Vec3(0, targetY, 0) }, { easing: 'quadIn' });
    }

    /**
     * 把一個符號節點 tween 到目標狀態，回一個到站才 resolve 的 promise。
     *
     * 消除、掉落、補位這幾段演出本來各自寫一份一模一樣的
     * 「`new Promise` 包 `Tween.stopAllByTarget` ＋ `tween().delay().to().call(resolve)`」，
     * 收斂成這一支：呼叫端只要描述「要變成什麼樣子」，不必再處理 promise 接線。
     *
     * 開始前一律先 `stopAllByTarget`：連鎖消除時同一個節點可能還有上一輪沒跑完的 tween，
     * 不清掉會兩個 tween 同時寫 position，節點會抖或停在錯的位置。
     *
     * @param node 目標節點。
     * @param duration 動畫秒數。
     * @param props 目標狀態（position／scale 等），直接交給 `Tween.to()`。
     * @param opts `delay` 起跑前的等待秒數；`easing` 緩動名稱；`onArrive` 到站後、resolve 之前執行。
     * @returns 到站之後 resolve。節點中途被銷毀時 tween 不會再推進，這個 promise 也不會 settle。
     */
    protected static tweenNodeTo(
        node: Node,
        duration: number,
        props: Record<string, unknown>,
        opts: { delay?: number; easing?: TweenEasing; onArrive?: () => void } = {}
    ): Promise<void> {
        return new Promise<void>((resolve) => {
            Tween.stopAllByTarget(node);

            // 用 `!== undefined` 而不是 truthy：原本的寫法在 delay 是 0 時仍然會排一個
            // `.delay(0)` 的動作，省掉它等於少走一次 tween 的排程，逐列 stagger 的起點會偏掉
            let t = tween(node);
            if (opts.delay !== undefined) t = t.delay(opts.delay);
            t = opts.easing ? t.to(duration, props, { easing: opts.easing }) : t.to(duration, props);

            t.call(() => {
                opts.onArrive?.();
                resolve();
            }).start();
        });
    }

    // ========== Tumble 消除機制 ==========

    /** 指定 row（0-based）爆炸消失：scale 縮到 0 後隱藏 */
    async explode(rows: number[], explodeTime: number): Promise<void> {
        const targetSet = new Set(rows.map((r) => r + this.rowToPosOffset));
        const promises: Promise<void>[] = [];
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (!targetSet.has(this.posIndexes[i])) continue;
            const node = this.symbolNodes[i];
            const opacity = this.symbolOpacities[i];
            // 縮到 0 之後改用 opacity 隱藏並把 scale 還原，節點才能直接重複使用
            const hide = (): void => {
                opacity.opacity = 0;
                node.setScale(1, 1, 1);
            };

            promises.push(ReelView.tweenNodeTo(node, explodeTime, { scale: new Vec3(0, 0, 1) }, { easing: 'backIn', onArrive: hide }));
        }
        await Promise.all(promises);
    }

    /** 把上方 symbol 往下掉補空位，回傳掉落結束後還空著的 posIdx 清單 */
    async drop(explodedRows: number[], dropTime: number, dropRowDelay: number): Promise<number[]> {
        const emptySet = new Set(explodedRows.map((r) => r + this.rowToPosOffset));
        const promises: Promise<void>[] = [];
        let dropCount = 0;

        for (let toPos = this.posList.length - 1; toPos >= 2; toPos--) {
            if (!emptySet.has(toPos)) continue;

            // 從 toPos 往上找最近的非空位置
            let fromPos = toPos - 1;
            while (fromPos >= 0 && emptySet.has(fromPos)) fromPos--;
            if (fromPos < 0) continue;

            const symIdx = this.findSymbolNodeAtPosIndex(fromPos);
            if (symIdx < 0) continue;

            this.posIndexes[symIdx] = toPos;
            emptySet.delete(toPos);
            emptySet.add(fromPos);

            const node = this.symbolNodes[symIdx];
            const targetY = this.posList[toPos].position.y;
            const delay = dropCount * dropRowDelay;
            dropCount++;

            promises.push(ReelView.tweenNodeTo(node, dropTime, { position: new Vec3(0, targetY, 0) }, { delay }));
        }
        this.updateDrawOrder();
        await Promise.all(promises);
        return Array.from(emptySet);
    }

    /** 新的 symbol 從畫面上方掉入，補滿剩下的空位 */
    async fill(emptyPosIdxs: number[], newSymbolNames: string[], fillTime: number, dropRowDelay: number): Promise<void> {
        emptyPosIdxs = [...emptyPosIdxs].reverse();
        newSymbolNames = [...newSymbolNames].reverse();
        const cellHeight = this.posList[0].position.y - this.posList[1].position.y;
        const startY = this.posList[0].position.y + cellHeight;
        const promises: Promise<void>[] = [];
        const map = this.getSymbolNameMap();

        for (let i = 0; i < emptyPosIdxs.length; i++) {
            const posIdx = emptyPosIdxs[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;

            const imgName = map[newSymbolNames[i]] ?? newSymbolNames[i];
            const frameIdx = Math.max(0, this.frameIdxByName(imgName));

            this.setSymbolDisplay(symIdx, frameIdx);
            this.symbolOpacities[symIdx].opacity = 255;
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            this.symbolNodes[symIdx].setPosition(0, startY, 0);

            const targetY = this.posList[posIdx].position.y;
            const node = this.symbolNodes[symIdx];
            const delay = i * dropRowDelay;

            promises.push(ReelView.tweenNodeTo(node, fillTime, { position: new Vec3(0, targetY, 0) }, { delay }));
        }
        await Promise.all(promises);
    }

    /** 全部 visible symbol 往下清空出畫面 */
    async tumbleClear(clearTime: number, rowDelay: number = 0.05): Promise<void> {
        const promises: Promise<void>[] = [];
        const dropOrder: number[] = [];
        for (let i = this.posList.length - 1; i >= 2; i--) dropOrder.push(i);

        for (let i = 0; i < dropOrder.length; i++) {
            const posIdx = dropOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;
            const node = this.symbolNodes[symIdx];
            const opacity = this.symbolOpacities[symIdx];
            const targetY = this.posList[this.posList.length - 1].position.y - 200;

            promises.push(
                ReelView.tweenNodeTo(node, clearTime, { position: new Vec3(0, targetY, 0) }, {
                    delay: i * rowDelay,
                    onArrive: () => (opacity.opacity = 0),
                })
            );
        }
        await Promise.all(promises);
    }

    /** 用新的 symbol 名稱重新從上方掉入，填滿整個 visible 盤面 */
    async tumbleFill(newSymbolNames: string[], fillTime: number, rowDelay: number = 0.05, onFirstLanded?: () => void): Promise<void> {
        const cellHeight = this.posList[0].position.y - this.posList[1].position.y;
        const startY = this.posList[0].position.y + cellHeight;
        const promises: Promise<void>[] = [];
        const fillOrder: number[] = [];
        for (let i = this.posList.length - 1; i >= 2; i--) fillOrder.push(i);
        const map = this.getSymbolNameMap();

        for (let i = 0; i < fillOrder.length; i++) {
            const posIdx = fillOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;

            const nameIdx = fillOrder.length - 1 - i;
            const imgName = map[newSymbolNames[nameIdx]] ?? newSymbolNames[nameIdx];
            const frameIdx = Math.max(0, this.frameIdxByName(imgName));

            this.setSymbolDisplay(symIdx, frameIdx);
            this.symbolOpacities[symIdx].opacity = 255;
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            this.symbolNodes[symIdx].setPosition(0, startY, 0);

            const targetY = this.posList[posIdx].position.y;
            const node = this.symbolNodes[symIdx];

            promises.push(
                new Promise<void>((resolve) => {
                    Tween.stopAllByTarget(node);
                    tween(node)
                        .delay(i * rowDelay)
                        .to(fillTime, { position: new Vec3(0, targetY, 0) })
                        .call(() => onFirstLanded?.())
                        .call(() => resolve())
                        .start();
                })
            );
        }
        await Promise.all(promises);
    }

    /** cascadeFill 共用 掉落到 targetY（彈跳開始前觸發 onFirstLanded）> 落地彈跳 > 落定 */
    private playCascadeDrop(node: Node, targetY: number, delay: number, duration: number, cellHeight: number, symIdx: number, fillEase: TweenEasing, onFirstLanded?: () => void): Promise<void> {
        return new Promise<void>((resolve) => {
            Tween.stopAllByTarget(node);
            let t = tween(node)
                .delay(delay)
                .to(duration, { position: new Vec3(0, targetY, 0) }, { easing: fillEase })
                .call(() => onFirstLanded?.());
            t = this.appendLandingBounce(t, targetY, cellHeight);
            t.call(() => {
                this.onSymbolSettled(symIdx);
                resolve();
            }).start();
        });
    }

    async cascadeFill(
        toMapCol: number[],
        elimRows: number[], // 這次被消除的 row（0-based，可見範圍）
        fillTime: number,
        dropRowDelay: number,
        onFirstLanded?: () => void,
        fillEase: TweenEasing = 'quadIn'
    ): Promise<void> {
        const len = this.posList.length;
        const keepRow = this.rowToPosOffset;
        // 最後一列資料格的 posIdx。用資料列數算而不是 len - 3：可視區裡若有裝飾格
        // （不吃後端資料、只跟著演出），len 會比資料列數多，照舊式算法會把裝飾格當成
        // 資料列去抓 toMapCol[該列]，取到 undefined 又不會報錯，那一格會變成空白。
        const visibleBottom = keepRow + this.dataRowCount - 1;
        const empty = new Set<number>(elimRows.map((r) => r + keepRow));
        const isEmpty = (p: number) => empty.has(p);
        const promises: Promise<void>[] = [];
        let dropCount = 0;
        const cellHeight = this.cellHeightAbs();

        for (let toPos = len - 1; toPos > 0; toPos--) {
            if (!isEmpty(toPos)) continue;

            let solidPos = toPos - 1;
            while (solidPos >= 0 && isEmpty(solidPos)) solidPos--;
            if (solidPos < 0) {
                // 上面已經沒東西可以掉了（buffer 用完），toPos 又在可見範圍內，做 ghost revive：直接生一個新的補進來
                if (toPos < keepRow || toPos > visibleBottom) continue;
                const ghostIdx = this.findSymbolNodeAtPosIndex(toPos);
                if (ghostIdx < 0) continue;
                const viewRow = toPos - keepRow;
                this.symbolOpacities[ghostIdx].opacity = 255;
                this.symbolNodes[ghostIdx].setScale(1, 1, 1);
                this.symbolNodes[ghostIdx].setPosition(0, this.posList[0].position.y, 0);
                this.setSymbolDisplay(ghostIdx, toMapCol[viewRow]);
                empty.delete(toPos);

                const ghostNode = this.symbolNodes[ghostIdx];
                const ghostTargetY = this.posList[toPos].position.y;
                const ghostDelay = dropCount * dropRowDelay;
                dropCount++;
                const ghostDist = this.posList[0].position.y - ghostTargetY;
                const ghostDuration = this.physicsFallDuration(ghostDist, cellHeight, fillTime);
                promises.push(this.playCascadeDrop(ghostNode, ghostTargetY, ghostDelay, ghostDuration, cellHeight, ghostIdx, fillEase, onFirstLanded));
                continue;
            }

            const emptySymIdx = this.findSymbolNodeAtPosIndex(toPos);
            const solidSymIdx = this.findSymbolNodeAtPosIndex(solidPos);

            if (emptySymIdx < 0 || solidSymIdx < 0) {
                console.error(`[cascadeFill] symbol not found: toPos =${toPos} solidPos =${solidPos}`);
                return;
            }

            this.posIndexes[emptySymIdx] = solidPos;
            this.symbolNodes[emptySymIdx].setPosition(0, this.posList[solidPos].position.y, 0);

            this.posIndexes[solidSymIdx] = toPos;
            this.symbolOpacities[solidSymIdx].opacity = 255;
            this.symbolNodes[solidSymIdx].setScale(1, 1, 1);
            this.symbolNodes[solidSymIdx].setPosition(0, this.posList[solidPos].position.y, 0);

            if (toPos >= keepRow && toPos <= visibleBottom) {
                const viewRow = toPos - keepRow;
                this.setSymbolDisplay(solidSymIdx, toMapCol[viewRow]);
            } else {
                const newRng = this.model.currentRng - elimRows.length;
                const stripIdx = (((newRng + toPos) % this.strip.length) + this.strip.length) % this.strip.length;
                this.setSymbolDisplay(solidSymIdx, this.strip[stripIdx]);
            }
            empty.delete(toPos);
            empty.add(solidPos);

            const node = this.symbolNodes[solidSymIdx];
            const targetY = this.posList[toPos].position.y;
            const delay = dropCount * dropRowDelay;
            dropCount++;
            const dist = this.posList[solidPos].position.y - targetY;
            const duration = this.physicsFallDuration(dist, cellHeight, fillTime);
            promises.push(this.playCascadeDrop(node, targetY, delay, duration, cellHeight, solidSymIdx, fillEase, onFirstLanded));
        }
        this.updateDrawOrder();
        await Promise.all(promises);
        this.model.setCurrentRng(this.model.currentRng - elimRows.length);
    }
}
