import { _decorator, SpriteFrame } from 'cc';

const { ccclass, property } = _decorator;

/**
 * 一個按鈕型態所需要的三張圖。
 *
 * lobby 的 BaseButton 把型態寫成固定的顏色 enum（Gray／Green／Red…），因為大廳的按鈕
 * 共用同一套底圖。1003 不是這樣：turbo 有 speed1／2／3 三檔、spin 有 default／spinning／
 * auto／feature 四種、menu 跟 shop 只有一種，每顆按鈕的「型態」互不相干。所以改成由
 * prefab 自己列一個陣列，不預先寫死語意。
 *
 * `hover` 與 `disable` 留空時會退回 `normal`，美術只出了一張圖的按鈕不必硬湊。
 */
@ccclass('1003/ButtonVariant')
export class ButtonVariant {
    @property({ displayName: '型態名稱', tooltip: '給 setVariant() 用的識別字，例如 speed1' })
    name: string = '';

    @property({ type: SpriteFrame, displayName: '一般' })
    normal: SpriteFrame = null!;

    @property({ type: SpriteFrame, displayName: '懸浮（PC）', tooltip: '留空時用一般圖' })
    hover: SpriteFrame = null!;

    @property({ type: SpriteFrame, displayName: '禁用', tooltip: '留空時用一般圖' })
    disable: SpriteFrame = null!;
}
