import { Material, Node, NodePool, RealCurve, Sprite, SpriteFrame, tween, Tween, UIOpacity, Vec3 } from 'cc';

/**
 * 飛行特效的共用核心：曲射路徑、距離換算、光暈／閃光、殘影。
 *
 * 從 `MultiplierFlyEffect` 抽出來的，原始出處是 1001 的 `CollectMulEffect.ts`（倍率球收球曲射）。
 * 1003 有兩個同型的演出——階梯倍數飛向累計條、加局時 Scatter 飛向 Spin 鈕——兩邊的路徑算法、
 * 時間換算與發射／抵達的光暈完全一樣，差別只在起訖點、要不要帶 spine、以及一次飛幾發，所以共用
 * 這一支，各自只留自己的那幾行。
 *
 * **這支不碰 `GameViewAdapter`。** 曲線、貼圖、材質都由呼叫端傳進來，才不會把兩個效果的欄位
 * 綁在一起。
 */

/** 飛行時間的參考距離（像素）；實際時間依起訖距離等比縮放 */
const REFERENCE_DISTANCE = 600;
const MIN_DURATION = 0.12;

/** 曲射幅度：垂直於起訖連線的最大偏移 = 距離 × 此比例 */
const ARC_RATIO = 0.15;

// 圖的縮放：越靠近終點越小，以 REFERENCE_DISTANCE 當一般距離基準
const MUL_SCALE_NEAR = 0.6;
const MUL_SCALE_FAR = 0.9;

const GHOST_INTERVAL = 0.02;
const GHOST_DURATION = 0.35;
const GHOST_OPACITY = 160;
const GHOST_END_SCALE = 0.6;

// 光暈／閃光
const BURST_DURATION = 0.3;
const BURST_START_SCALE = 0.4;
const BURST_END_SCALE = 1.3;
const BURST_START_OPACITY = 220;
/** glow 疊在 aura 之後，差這麼多秒 */
const GLOW_DELAY = 0.12;

/** 殘影節點池 */
const ghostPool = new NodePool();

/**
 * 建立一個掛好 Sprite 的節點。
 *
 * @param name 節點名稱。
 * @param parent 父節點。
 * @param frame 貼圖。
 * @returns 新節點。
 */
export function createVisualNode(name: string, parent: Node, frame: SpriteFrame): Node {
    const node = new Node(name);

    parent.addChild(node);
    node.addComponent(Sprite).spriteFrame = frame;

    return node;
}

/**
 * 依距離決定圖的縮放，越靠近終點越小。
 *
 * @param from 起點。
 * @param to 終點。
 * @returns 縮放倍率。
 */
export function resolveScale(from: Vec3, to: Vec3): number {
    const distance = Vec3.distance(from, to);
    const t = Math.min(1, distance / REFERENCE_DISTANCE);

    return MUL_SCALE_NEAR + (MUL_SCALE_FAR - MUL_SCALE_NEAR) * t;
}

/**
 * 把曲線正規化成「0 到 1 的進度」。
 *
 * 曲線的首尾值是多少都不影響結果，所以美術在 Inspector 上隨意畫也不會讓終點跑掉。
 *
 * @param curve 移動曲線。
 * @returns 時間 0~1 對應進度 0~1 的函式。
 */
export function buildMoveEvaluator(curve: RealCurve): (t: number) => number {
    const v0 = curve.evaluate(0);
    const span = curve.evaluate(1) - v0 || 1;

    return (t) => (curve.evaluate(t) - v0) / span;
}

/**
 * 把曲線轉成「垂直偏移比例」：先扣掉首尾的線性趨勢，再除以峰值正規化成 ±1。
 *
 * 去趨勢是關鍵——這樣不管曲線頭尾畫在哪，起點與終點的偏移都是 0，飛行一定落在目標上。
 * 曲線畫成一條直線（峰值為 0）時退回預設的拋物線，不然就完全沒有弧度。
 *
 * @param curve 高度曲線。
 * @returns 時間 0~1 對應偏移比例的函式。
 */
export function buildHeightEvaluator(curve: RealCurve): (t: number) => number {
    const v0 = curve.evaluate(0);
    const v1 = curve.evaluate(1);
    const detrend = (t: number) => curve.evaluate(t) - (v0 + (v1 - v0) * t);

    let peak = 0;
    for (let i = 0; i <= 20; i++) {
        peak = Math.max(peak, Math.abs(detrend(i / 20)));
    }

    return peak < 1e-3 ? (t) => 4 * t * (1 - t) : (t) => detrend(t) / peak;
}

/**
 * 在來源節點當下的位置留一張殘影，淡出後縮小並回收進節點池。
 *
 * @param parent 殘影掛在哪。
 * @param source 要複製位置／旋轉／縮放的節點。
 * @param frame 貼圖。
 */
export function spawnGhost(parent: Node, source: Node, frame: SpriteFrame): void {
    let ghost = ghostPool.get();

    if (ghost) {
        parent.addChild(ghost);
        const sprite = ghost.getComponent(Sprite) ?? ghost.addComponent(Sprite);
        sprite.spriteFrame = frame;
    } else {
        ghost = createVisualNode('multiplierFlyGhost', parent, frame);
    }

    ghost.setWorldPosition(source.getWorldPosition());
    ghost.setWorldRotation(source.worldRotation);
    ghost.setWorldScale(source.worldScale);
    Tween.stopAllByTarget(ghost);

    const opacity = ghost.getComponent(UIOpacity) ?? ghost.addComponent(UIOpacity);
    Tween.stopAllByTarget(opacity);
    opacity.opacity = GHOST_OPACITY;

    tween(opacity).to(GHOST_DURATION, { opacity: 0 }, { easing: 'quadOut' }).start();

    tween(ghost)
        .to(GHOST_DURATION, { scale: new Vec3(GHOST_END_SCALE, GHOST_END_SCALE, 1) })
        .call(() => ghostPool.put(ghost!))
        .start();
}

/**
 * 原地放大淡出的一張光暈／閃光，播完自己銷毀。
 *
 * @param parent 掛在哪。
 * @param worldPos 播放位置。
 * @param frame 貼圖；null 時整段跳過。
 * @param material 去背材質（黑底圖用）；留空照原本混合模式顯示。
 */
export function playBurst(parent: Node, worldPos: Vec3, frame: SpriteFrame | null, material?: Material | null): void {
    if (!frame) return;

    const node = createVisualNode('multiplierFlyBurst', parent, frame);
    node.setWorldPosition(worldPos);
    node.setScale(BURST_START_SCALE, BURST_START_SCALE, 1);

    if (material) {
        node.getComponent(Sprite)!.customMaterial = material;
    }

    const opacity = node.addComponent(UIOpacity);
    opacity.opacity = BURST_START_OPACITY;

    tween(node)
        .to(BURST_DURATION, { scale: new Vec3(BURST_END_SCALE, BURST_END_SCALE, 1) }, { easing: 'quadOut' })
        .start();

    tween(opacity)
        .to(BURST_DURATION, { opacity: 0 }, { easing: 'quadOut' })
        .call(() => node.isValid && node.destroy())
        .start();
}

/**
 * 整組疊播同一個位置的光暈。
 *
 * @param parent 掛在哪。
 * @param worldPos 播放位置。
 * @param frames 整疊貼圖；空陣列就什麼都不做。
 * @param material 去背材質。
 */
export function playBurstGroup(parent: Node, worldPos: Vec3, frames: SpriteFrame[], material?: Material | null): void {
    for (const frame of frames) {
        playBurst(parent, worldPos, frame, material);
    }
}

/**
 * 在節點樹裡找第一張「亮著的」貼圖。
 *
 * 只往 `active` 的子節點走，所以一階的 ON／OFF 兩個子節點只會命中 ON 那張——不必知道
 * `BaseToggle` 的內部結構，也不會在版面重排後失準。
 *
 * @param node 起點節點。
 * @returns 找到的貼圖；整棵樹都沒有 Sprite 時是 null。
 */
export function findActiveFrame(node: Node): SpriteFrame | null {
    const own = node.getComponent(Sprite)?.spriteFrame ?? null;
    if (own) return own;

    for (const child of node.children) {
        if (!child.active) continue;

        const found = findActiveFrame(child);
        if (found) return found;
    }

    return null;
}

/** 常數也要給呼叫端：距離換算與光暈的延遲都是同一組基準 */
export { REFERENCE_DISTANCE, MIN_DURATION, ARC_RATIO, GLOW_DELAY };

/**
 * 取得（必要時建立）一個特效容器節點。
 *
 * 飛行本體、殘影、光暈都掛在它底下，不要散在 view 的根節點上。
 *
 * @param parent 容器要掛在誰底下。
 * @param name 容器節點名稱。
 * @returns 容器節點。
 */
export function resolveFlyContainer(parent: Node, name: string): Node {
    let root = parent.getChildByName(name);

    if (!root) {
        root = new Node(name);
        parent.addChild(root);
    }

    return root;
}

/**
 * 依起訖距離換算飛行時間：距離近的自動變快，並夾在下限與參考值之間。
 *
 * @param reference 參考距離（{@link REFERENCE_DISTANCE}）下的秒數。
 * @param from 起點世界座標。
 * @param to 終點世界座標。
 * @returns 秒數。
 */
export function resolveArcDuration(reference: number, from: Vec3, to: Vec3): number {
    const distance = Vec3.distance(from, to);
    const speed = REFERENCE_DISTANCE / reference;

    return Math.min(reference, Math.max(MIN_DURATION, distance / speed));
}

/** {@link flyAlongArc} 的選項 */
export interface FlyArcOptions {
    /** 起點世界座標 */
    from: Vec3;
    /** 終點世界座標 */
    to: Vec3;
    /** 飛行秒數 */
    duration: number;
    /** 時間 0~1 對應沿連線的進度 */
    moveCurve: RealCurve;
    /** 時間 0~1 對應垂直於連線的抬高比例 */
    heightCurve: RealCurve;
    /** 讓節點轉向飛行方向。帶尾巴的 spine 通常不要（會扭成一團），貼圖才要 */
    faceDirection?: boolean;
    /** 沿途殘影要用的貼圖；不給就沒有殘影 */
    ghostFrame?: SpriteFrame | null;
    /** 殘影掛在哪；不給就掛在飛行節點的父節點 */
    ghostParent?: Node | null;
    /** 每幀回呼，給呼叫端同步其他節點（例如跟著飛的 spine） */
    onStep?: (pos: Vec3, ratio: number) => void;
}

/**
 * 讓一個節點沿曲射路徑從起點飛到終點。
 *
 * 曲線的首尾值畫在哪都不影響落點（見 {@link buildMoveEvaluator}／{@link buildHeightEvaluator}
 * 的正規化），所以美術在 Inspector 上隨意畫也不會讓終點跑掉。
 *
 * @param node 要飛的節點。
 * @param opt 選項，見 {@link FlyArcOptions}。
 * @returns 抵達終點後 resolve。節點中途被銷毀時 tween 不會回呼，呼叫端不要把關鍵流程掛在這個
 *          Promise 上（踩坑 #35），要等就等「該飛多久」那個時間。
 */
export function flyAlongArc(node: Node, opt: FlyArcOptions): Promise<void> {
    const { from, to, duration } = opt;
    const moveT = buildMoveEvaluator(opt.moveCurve);
    const heightT = buildHeightEvaluator(opt.heightCurve);

    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const distance = Math.sqrt(dx * dx + dy * dy) || 1;
    const perpX = -dy / distance;
    const perpY = dx / distance;
    const arcHeight = distance * ARC_RATIO;

    const pos = new Vec3();
    const ahead = new Vec3();
    let nextGhostTime = 0;

    const getPosition = (t: number, out: Vec3): void => {
        const move = moveT(t);
        const height = heightT(t);

        out.set(
            from.x + dx * move + perpX * height * arcHeight,
            from.y + dy * move + perpY * height * arcHeight,
            from.z + (to.z - from.z) * move
        );
    };

    return new Promise<void>((resolve) => {
        tween(node)
            .update(duration, (_target, ratio) => {
                getPosition(ratio, pos);
                node.setWorldPosition(pos);
                opt.onStep?.(pos, ratio);

                if (opt.faceDirection) {
                    // 取稍微往前一點的位置算切線
                    getPosition(Math.min(ratio + 0.02, 1), ahead);
                    const faceX = ahead.x - pos.x;
                    const faceY = ahead.y - pos.y;

                    if (faceX || faceY) {
                        node.angle = (Math.atan2(-faceX, faceY) * 180) / Math.PI;
                    }
                }

                if (opt.ghostFrame && ratio * duration >= nextGhostTime) {
                    spawnGhost(opt.ghostParent ?? node.parent!, node, opt.ghostFrame);
                    nextGhostTime = ratio * duration + GHOST_INTERVAL;
                }
            })
            .call(() => resolve())
            .start();
    });
}
