import { GameTask } from './GameTask';

export interface GameTaskQueueOptions {
    /** 除錯用名稱，設定後每顆任務開始/結束都會 log */
    debugName?: string;
}

/**
 * GameTaskQueue
 *
 * 頂層任務佇列執行器，對應 SGEngine 的 GameMain：
 * - addTask() 把任務推進佇列；佇列閒置時立即開始執行，忙碌時排隊等待。
 * - 任務可以在 onStart() 執行過程中呼叫 addTask() 動態插入後續任務
 *   （對應 SGEngine 的 SGNetHandler 在解析封包當下組裝一串 Task 的模式）。
 * - 嚴格循序消費：前一顆完全 finish 才會開始下一顆。
 *
 * 用法範例（取代 GameContext 內手寫的 async/await 串接）：
 *   const queue = new GameTaskQueue();
 *   queue.addTask(new GameTaskPromise(() => this.playCascadeReels(steps)));
 *   queue.addTask(new GameTaskDelay(300));
 *   queue.addTask(new GameTaskFn(() => this.applyMultiplierLabels(cols, sides)));
 */
export class GameTaskQueue {
    private readonly pending: GameTask[] = [];
    private current: GameTask | null = null;
    private readonly onIdleCallbacks = new Set<() => void>();

    /**
     * @param options 佇列的除錯名稱等設定。
     */
    constructor(private readonly options: GameTaskQueueOptions = {}) {}

    /** 是否閒置中（沒有正在執行、也沒有排隊中的任務） */
    public get isIdle(): boolean {
        return this.current === null && this.pending.length === 0;
    }

    /** 目前排隊中（不含正在執行）的任務數量 */
    public get pendingCount(): number {
        return this.pending.length;
    }

    /** 加入任務；佇列閒置時立即開始執行 */
    public addTask(task: GameTask): void {
        this.pending.push(task);
        if (this.options.debugName) {
            console.log(`[GameTaskQueue:${this.options.debugName}] enqueued, pending=${this.pending.length}`);
        }
        if (this.current === null) this.runNext();
    }

    /** 佇列變為閒置時觸發一次；若呼叫當下已閒置則立即觸發 */
    public onceIdle(callback: () => void): void {
        if (this.isIdle) {
            callback();
            return;
        }
        this.onIdleCallbacks.add(callback);
    }

    /**
     * 清空尚未執行的任務（不會中斷正在執行中的任務）。
     * 用於例如「玩家點了 buy feature，取消上一輪還沒播完的排隊演出」等情境。
     */
    public clearPending(): void {
        this.pending.length = 0;
    }

    /**
     * 取出下一個 task 執行；沒有排隊中的就轉為閒置並觸發 idle 回呼。
     */
    private runNext(): void {
        const task = this.pending.shift();
        if (!task) {
            this.current = null;
            this.flushIdleCallbacks();
            return;
        }

        this.current = task;
        if (this.options.debugName) {
            console.log(`[GameTaskQueue:${this.options.debugName}] start task=${task.constructor.name}`);
        }
        task.execute(() => {
            if (this.options.debugName) {
                console.log(`[GameTaskQueue:${this.options.debugName}] finish task=${task.constructor.name}`);
            }
            this.runNext();
        });
    }

    /**
     * 把等待閒置的回呼全部觸發並清空。
     *
     * 先複製再走訪：回呼裡很可能又排新的 task 或再登記一個 idle 回呼。
     */
    private flushIdleCallbacks(): void {
        if (this.onIdleCallbacks.size === 0) return;
        const callbacks = Array.from(this.onIdleCallbacks);
        this.onIdleCallbacks.clear();
        for (const cb of callbacks) cb();
    }
}
