export type SlotSymbolKind = 'normal' | 'scatter' | 'multiplier' | 'jackpot' | 'wild';

export interface SlotSymbolInfo {
    readonly id: number;
    readonly kind: SlotSymbolKind;
    readonly value: number;
    readonly upgradeable: boolean;
    readonly colorTier: number;
    readonly name: string;
}

export interface SlotSymbolMetadata {
    readonly name?: string;
    readonly multiplier?: number;
}

export interface SlotSymbolFrameContext {
    readonly id: number;
    readonly side: number;
    readonly symbol: SlotSymbolInfo;
}

export type SlotSymbolFrame = string | ((context: SlotSymbolFrameContext) => string);

/** 一個後端 Symbol ID 的完整遊戲層定義，不要求 ID 連號或遵循任何命名規則。 */
export interface SlotSymbolDefinition {
    readonly id: number;
    readonly kind: SlotSymbolKind;
    readonly frame: SlotSymbolFrame;
    readonly name?: string;
    readonly value?: number;
    readonly upgradeable?: boolean;
    readonly colorTier?: number;
}

export interface SlotSymbolFallback {
    readonly kind?: SlotSymbolKind;
    readonly frame: SlotSymbolFrame;
    readonly name?: string;
}

export interface SlotSymbolCatalogConfig {
    readonly symbols: readonly SlotSymbolDefinition[];
    readonly fallback: SlotSymbolFallback;
}

export interface SlotSymbolCatalog {
    resolve(id: number, metadataById?: ReadonlyMap<number, SlotSymbolMetadata>): SlotSymbolInfo;
    frameName(id: number, side?: number): string;
}

export interface SlotGameDefinition {
    readonly symbols: SlotSymbolCatalog;
}

/** 共用層只負責查表與補預設值；ID、種類、倍率、顏色及資源名稱由各遊戲宣告。 */
export function createSlotSymbolCatalog(config: SlotSymbolCatalogConfig): SlotSymbolCatalog {
    const definitions = new Map<number, SlotSymbolDefinition>();
    for (const definition of config.symbols) {
        if (definitions.has(definition.id)) throw new Error(`Duplicate slot symbol id: ${definition.id}`);
        definitions.set(definition.id, definition);
    }

    const resolve = (id: number, metadataById?: ReadonlyMap<number, SlotSymbolMetadata>): SlotSymbolInfo => {
        const definition = definitions.get(id);
        const metadata = metadataById?.get(id);
        return {
            id,
            kind: definition?.kind ?? config.fallback.kind ?? 'normal',
            value: metadata?.multiplier ?? definition?.value ?? 0,
            upgradeable: definition?.upgradeable ?? false,
            colorTier: definition?.colorTier ?? 0,
            name: metadata?.name ?? definition?.name ?? config.fallback.name ?? 'unknown',
        };
    };

    return {
        resolve,
        /**
         * 取得某個符號要用哪張圖。
         *
         * `frame` 可以登記成固定字串或函式，函式版本才能依 id／邊數算出不同的圖
         * （例如同一個符號在不同連線長度下換圖）。
         *
         * @param id 符號 id。
         * @param side 連線邊數，預設 1。
         * @returns 圖片名稱。
         */
        frameName(id: number, side: number = 1): string {
            const symbol = resolve(id);
            const frame = definitions.get(id)?.frame ?? config.fallback.frame;
            return typeof frame === 'function' ? frame({ id, side, symbol }) : frame;
        },
    };
}
