import { _decorator } from 'cc';
import { BaseUIComponent } from './BaseUIComponent';
import { BaseToggle } from './BaseToggle';

const { ccclass, property } = _decorator;

/**
 * 一組互斥的 BaseToggle：同一時間最多只有一顆亮。
 *
 * 直屬子節點上的 BaseToggle 由 onLoad() 主動收集，不必手動呼叫 register()。
 *
 * 原本從 1001 複製（2026-09-22），2026-09-23 起這份不再與 1001／entry 的 GameToggleGroup
 * 一致——改掉了初始化時序：
 *
 * 舊版只等子節點的 BaseToggle 在它們自己的 onLoad 裡回頭註冊。但 Cocos 是父節點的元件
 * onLoad 先跑、子節點後跑，所以群組的 onLoad 當下 `_toggles` 還是空的，預設選取只好用
 * `scheduleOnce(…, 0)` 推遲一幀——而那個延遲呼叫會把同一幀裡程式碼做的選取蓋掉，逼得每個
 * 使用端都要記得同步 defaultIndex（agent-pitfalls.md 坑 #9）。
 *
 * 現在改成群組自己在 onLoad 掃一次子節點，預設選取就能在 start() 同步套用；而且
 * defaultIndex 只是「預設」，已經有人明確選過就讓位，不再覆蓋。子節點的自我註冊保留，
 * 當作執行期才搬進來的 Toggle 的補登記。
 *
 * 仍然存在的限制：沒有 unregister／clear()，不適合動態增減 Toggle 節點
 * （agent-pitfalls.md 坑 #7）。
 */
@ccclass('1003/BaseToggleGroup')
export class BaseToggleGroup extends BaseUIComponent {
    @property({ displayName: '預設選取第幾顆', tooltip: '從 0 開始，0 = 第一顆，1 = 第二顆；-1 = 預設不選取任何一顆' })
    public defaultIndex: number = 0;

    private _toggles: BaseToggle[] = [];

    private _onToggleOn: ((index: number) => void) | null = null;

    /** 有沒有人明確選過（selectToggle／selectIndex）；有的話 start() 就不要用 defaultIndex 蓋掉 */
    private _hasExplicitSelection = false;

    /**
     * 設定 Toggle 點亮事件的回呼。
     *
     * @param callback 回呼，參數是點亮的那顆的索引；全部取消時是 -1。
     */
    public set OnToggleOn(callback: (index: number) => void) {
        this._onToggleOn = callback;
    }

    /**
     * 收集直屬子節點上的 BaseToggle。
     *
     * 只掃直屬子節點（不是 getComponentsInChildren），維持「只有直接掛在群組底下的那一層
     * 算群組成員」這個原本的語意——遞迴會把孫節點上的 Toggle 也收進來。
     */
    protected override onLoad(): void {
        for (const child of this.node.children) {
            const toggle = child.getComponent(BaseToggle);
            if (toggle) this.register(toggle);
        }
    }

    /**
     * 套用預設選取。
     *
     * 同步執行即可：Cocos 會把整棵樹的 onLoad 跑完才進 start 階段，該註冊的都註冊好了。
     * 已經有人明確選過就跳過——defaultIndex 是預設值，不該反過來覆蓋明確的選取。
     */
    protected override start(): void {
        if (this._hasExplicitSelection) return;
        this.selectIndex(this.defaultIndex);
    }

    /**
     * 把一顆 Toggle 加進群組，註冊當下先關掉。重複註冊會被忽略。
     *
     * @param toggle 要加入的 Toggle。
     */
    public register(toggle: BaseToggle): void {
        if (!toggle) return;
        if (this._toggles.includes(toggle)) return;

        this._toggles.push(toggle);

        // 註冊時先關掉，避免場景裡 ON 全部亮
        toggle.setToggle(false);
    }

    /**
     * 點亮指定的 Toggle、關掉其他顆，並通知回呼。不在群組裡的 Toggle 直接略過。
     *
     * @param toggle 要點亮的 Toggle。
     */
    public selectToggle(toggle: BaseToggle): void {
        const index = this._toggles.indexOf(toggle);
        if (index < 0) return;

        this._hasExplicitSelection = true;

        this._toggles.forEach((item) => {
            item.setToggle(item === toggle);
        });

        this._onToggleOn?.(index);
    }

    /**
     * 依索引選取。負數代表全部取消；超出範圍時夾到最近的一顆。
     *
     * @param index 要選取的索引，-1 = 全部不選。
     */
    public selectIndex(index: number): void {
        if (this._toggles.length <= 0) return;

        if (index < 0) {
            // 「明確取消全選」也算一次明確選取，start() 同樣不該用 defaultIndex 蓋掉它
            this._hasExplicitSelection = true;
            this._toggles.forEach((item) => item.setToggle(false));
            this._onToggleOn?.(-1);
            return;
        }

        const safeIndex = Math.max(0, Math.min(index, this._toggles.length - 1));
        const toggle = this._toggles[safeIndex];

        this.selectToggle(toggle);
    }

    /**
     * 回到預設選取。
     */
    public reset(): void {
        this.selectIndex(this.defaultIndex);
    }
}
