import { _decorator, Component, Node, Tween, tween, Vec3 } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('1003/SpinnerView')
export class SpinnerView extends Component {


    /**
     * 開始轉圈。
     */
    override start() {
        this.startSpinner();
    }


    /**
     * 啟動無限循環的旋轉動畫。
     */
    startSpinner() {
        tween(this.node)
            .by(0.5, { eulerAngles: new Vec3(0, 0, -360) })
            .repeatForever()
            .start();
    }

    /**
     * 停掉旋轉動畫，避免節點銷毀後 tween 還在跑。
     */
    override onDestroy() {
        console.log('[SpinnerView] onDestroy');
        Tween.stopAllByTarget(this.node);
    }
}

