import { _decorator, Node, Size, tween, Tween, type TweenEasing, UIOpacity, UITransform, Vec3 } from 'cc';
import { ReelView } from './ReelView';
import type { SlotMachineView } from './SlotMachineView';
import { SymbolCell } from '../symbol/SymbolCell';
import { SymbolImageManager } from '../symbol/SymbolImageManager';
import { SymbolState, SymbolStateLevel } from '../symbol/SymbolState';
import { goldenSymbolIdOf, SLOT_GAME_DEFINITION, SYMBOL_IDS } from '../../config/SlotGameDefinition';

const { ccclass, property } = _decorator;

@ccclass('1003/ReelView_1003')
export class ReelView_1003 extends ReelView {
    /** posList 可視格上下各留幾格緩衝，讓符號有畫面外的進出空間；可見列 row 對應的 posList 索引是 row + BUFFER_SLOTS */
    static readonly BUFFER_SLOTS = 2;

    // 不規則輪帶（葫蘆型盤面）各欄可視列數可能不同：用可視列數、符號尺寸與 centerY 動態產生 posList，
    // 不用再手動擺放/刪除位置標記節點；base class 繼承來的 posList 欄位仍會顯示在 Inspector，
    // 但內容一律由這裡的 onLoad() 覆蓋產生，手動填的值不會被使用。
    @property({ tooltip: '這一欄可視列數（葫蘆型盤面：中間 3 欄填 5、兩側 2 欄填 6）' })
    private configuredVisibleRowCount: number = 5;

    @property({ tooltip: '可視區上下各有幾格是裝飾格（不吃後端資料，只跟著演出）。葫蘆型盤面兩側欄填 1、中間 3 欄填 0' })
    private decorativeEdgeRows: number = 0;

    @property({ tooltip: '可視區垂直置中的 Y 座標，5 欄應共用同一個值，讓不同列數的欄自動上下對齊置中' })
    private centerY: number = 0;

    /** 一格的寬×高，onLoad 時從所屬機台的 {@link SlotMachineView.symbolSize} 讀進來 */
    private readonly cellSize = new Size();

    /**
     * 讀機台的符號尺寸，套到這一欄的尺寸上，再依可視列數 / 符號高 / centerY 動態產生 posList。
     *
     * 葫蘆型盤面各欄可視列數不同（中間 3 欄 5 列、兩側 2 欄 4 列），手動擺位置標記節點
     * 太容易漏，所以這裡一律覆蓋掉 Inspector 上繼承來的 posList。
     * 上下各多留 {@link ReelView_1003.BUFFER_SLOTS} 格緩衝，讓符號有畫面外的進出空間。
     *
     * 列距就是符號高，格與格之間不留空。
     */
    protected override onLoad(): void {
        const size = this.resolveSymbolSize();
        if (!size) {
            console.error(`[ReelView_1003] ${this.node.name} 往上找不到 SlotMachineView，讀不到 symbolSize，所有格位會疊在同一個 Y`);
        }
        this.cellSize.set(size ?? Size.ZERO);
        this.applyColumnSize();

        const totalSlots = this.configuredVisibleRowCount + ReelView_1003.BUFFER_SLOTS * 2; // 上緩衝 + N 格可視 + 下緩衝
        const posList: Node[] = [];
        for (let i = 0; i < totalSlots; i++) {
            const marker = new Node(`pos_${i}`);
            const y = this.centerY + ((totalSlots - 1) / 2 - i) * this.cellSize.height;
            marker.setPosition(0, y, 0);
            this.node.addChild(marker);
            posList.push(marker);
        }
        this.posList = posList;
    }

    /**
     * 往上找所屬機台的符號尺寸。
     *
     * 用 ccclass 名稱字串查，不直接 import `SlotMachineView`：那支本來就 import 這支（`reelViews` 的型別），
     * 互相 import 會形成循環，Cocos 載入時 `@property([ReelView_1003])` 有機會拿到 undefined。
     *
     * @returns 機台上的符號尺寸；往上找不到機台時為 null。
     */
    private resolveSymbolSize(): Size | null {
        for (let node = this.node.parent; node; node = node.parent) {
            const machine = node.getComponent('1003/SlotMachineView') as SlotMachineView | null;
            if (machine) return machine.symbolSize;
        }
        return null;
    }

    /**
     * 欄節點與 Container 的尺寸跟著符號尺寸走：寬＝符號寬，高＝這一欄的可視列數 × 符號高。
     *
     * 機台排欄（`SlotMachineView.layoutReelColumns`）讀的是欄節點的寬，所以欄距自然等於符號寬。
     * 高度目前只影響 Editor 裡的框與特殊符號容器的尺寸——盤面裁切靠的是機台根節點上的 Mask。
     */
    private applyColumnSize(): void {
        const width = this.cellSize.width;
        const height = this.configuredVisibleRowCount * this.cellSize.height;
        this.node.getComponent(UITransform)?.setContentSize(width, height);
        this.container?.getComponent(UITransform)?.setContentSize(width, height);
    }

    @property({
        type: SymbolImageManager,
        tooltip: '符號顯示物件的物件池。留空時自動往上找最近的一顆（通常掛在 SlotMachineView 上）'
    })
    public symbolManager: SymbolImageManager = null!;

    /**
     * `spriteFrames` 索引 → 符號 id 的對照。
     *
     * 外部（CascadeReelsTask、base ReelView 的輪帶邏輯）仍然以 frameIdx 溝通，但 {@link SymbolCell}
     * 認的是符號 id。這張表在 {@link buildFrameIdxToSymbolId} 一次建好，避免每次換圖都做字串比對。
     *
     * 金牌 id（101–109）**也在這張表裡**：它有自己的一組圖（底牌圖名加 `_g`，例如 `H1_g`）與自己的
     * prefab，跟其他符號沒有兩樣。這是金牌能在掉落途中就是金的關鍵——詳見
     * {@link buildFrameIdxToSymbolId}。
     */
    private frameIdxToSymbolId: number[] = [];

    /**
     * 特殊符號層裡屬於這一欄的兩個容器，由 {@link SlotMachineView} 在 init 時配發。
     *
     * 盤面只有機台根節點上一個 Mask，各欄之間是依序整欄疊上去的——右欄的一般符號會蓋住左欄
     * 的 Scatter。所以 Scatter／Wild 的格子會整顆搬進這兩個容器：它們排在所有欄之後（全部 Wild
     * 容器在前、全部 Scatter 容器在後），做出 Scatter > Wild > 一般符號的疊放順序，而且仍在機台
     * 節點底下，被同一個 Mask 裁切。
     *
     * 搬的是**格子節點本身**而不是租來的符號圖：容器跟本欄的 Container 世界座標一致，格子的本地
     * 座標不用換算，轉動、落下、金牌翻面、透明度這些套在格子上的 tween 全部照舊。
     *
     * 沒配發（例如單獨測試一欄）時一律留在 Container，行為跟改版前一樣。
     */
    private specialContainers: { wild: Node; scatter: Node } | null = null;

    /** 上次對齊特殊容器時 Container 的世界座標，用來判斷要不要重新對齊 */
    private readonly lastContainerWorldPos = new Vec3(Number.NaN, Number.NaN, Number.NaN);

    /**
     * 拿到後端輪帶設定前的預設輪帶，值是 spriteFrames 的索引（0–8 為 H1–H4、L1–L5，9 scatter，
     * 10 wild，11–19 為對應的金牌版）。
     * 原本的 9–16 指向 1001 的倍率球圖，2026-09-14 隨素材刪除改成只含一般符號。
     */
    public override strip: number[] = [2, 2, 2, 5, 6, 7, 8, 0, 1, 3, 4, 5, 6, 7];

    /**
     * 這一轉的下注額。1003 已經沒有程式讀它（原本給 coin 符號算假金額，2026-09-14 隨 Jackpot 移除），
     * 保留只因為共用的 SlotGameMain 會對每個 reelView 寫入這個欄位。
     */
    public spinBet: number = 0;

    /** 金牌翻面成 Wild 的總時長（秒），前後各半 */
    private static readonly GOLDEN_FLIP_SEC = 0.24;


    /**
     * 建立這一欄的格子。
     *
     * 覆寫基底的 `initSymbols()` 而不是沿用它：基底是 `instantiate(symbolPrefab)`，整顆格子連同
     * 全部美術一起複製；改版後格子本身是**沒有任何美術的空殼**（只有 UITransform／UIOpacity／
     * {@link SymbolCell}），要顯示什麼由 cell 向 {@link symbolManager} 租。所以連 prefab 都不需要，
     * 直接 `new Node()` 建出來最乾淨，也少一份要維護的資產。
     *
     * 節點數量等於 posList 長度而不是可視列數：頭尾各留緩衝格，轉動時是搬位置而不是生成銷毀。
     */
    /**
     * 接上特殊符號層的兩個容器，並立刻對齊到本欄 Container 的世界座標。
     *
     * 要在 {@link init} 之前呼叫——建格子時就會依符號種類把格子放進對應容器。
     *
     * @param wild 放 Wild 格子的容器。
     * @param scatter 放 Scatter 格子的容器。
     */
    public attachSpecialContainers(wild: Node, scatter: Node): void {
        this.specialContainers = { wild, scatter };
        const size = this.container.getComponent(UITransform)?.contentSize;
        for (const node of [wild, scatter]) {
            if (size) (node.getComponent(UITransform) ?? node.addComponent(UITransform)).setContentSize(size);
        }
        this.lastContainerWorldPos.set(Number.NaN, Number.NaN, Number.NaN);
        this.syncSpecialContainers();
    }

    /**
     * 讓特殊容器的世界座標、旋轉、縮放跟 Container 一致，Container 沒動就什麼都不做。
     *
     * 目前沒有任何程式會在執行期移動欄節點或 Container，對齊一次就夠；每幀檢查是保險——
     * 哪天有人替整欄加了彈跳或位移，特殊符號才不會默默偏離自己的格位。
     */
    private syncSpecialContainers(): void {
        const sc = this.specialContainers;
        if (!sc) return;

        const pos = this.container.worldPosition;
        if (Vec3.equals(pos, this.lastContainerWorldPos)) return;
        this.lastContainerWorldPos.set(pos);

        for (const node of [sc.wild, sc.scatter]) {
            node.setWorldPosition(pos);
            node.setWorldRotation(this.container.worldRotation);
            node.setWorldScale(this.container.worldScale);
        }
    }

    protected override lateUpdate(): void {
        this.syncSpecialContainers();
    }

    /**
     * 符號的疊放順位，數字大的蓋在上面：Scatter 2、Wild 1、其他 0（金牌的 kind 是 normal，算其他）。
     *
     * @param symbolId 符號 id；-1（還沒設定）視為一般符號。
     * @returns 疊放順位。
     */
    private static drawRankOf(symbolId: number): number {
        if (symbolId < 0) return 0;
        const kind = SLOT_GAME_DEFINITION.symbols.resolve(symbolId).kind;
        if (kind === 'scatter') return 2;
        if (kind === 'wild') return 1;
        return 0;
    }

    /**
     * 依格子目前的符號，把格子節點放進 Container、Wild 容器或 Scatter 容器。
     *
     * 本地座標保持不變（容器之間世界座標一致），換了父節點之後重排一次疊放順序。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     */
    private placeCell(symbolIdx: number): void {
        const node = this.symbolNodes[symbolIdx];
        const cell = this.symbolCells[symbolIdx];
        if (!node || !cell) return;

        const sc = this.specialContainers;
        const rank = ReelView_1003.drawRankOf(cell.getSymbolId());
        const target = !sc ? this.container : rank === 2 ? sc.scatter : rank === 1 ? sc.wild : this.container;
        if (node.parent === target) return;

        node.setParent(target);
        this.updateDrawOrder();
    }

    /**
     * 每個容器各自依格位排序：越下面的格子疊在越上層。
     *
     * 基底只處理 Container 一個父節點；格子分散到三個容器之後，要對各自的父節點排，
     * 否則搬進特殊容器的格子會拿 Container 的子節點數去設 sibling index。
     */
    protected override updateDrawOrder(): void {
        const order = this.symbolNodes.map((_, i) => i).sort((a, b) => this.posIndexes[a] - this.posIndexes[b]);
        for (const i of order) {
            const node = this.symbolNodes[i];
            node.setSiblingIndex((node.parent?.children.length ?? 1) - 1);
        }
    }

    protected override initSymbols(): void {
        this.symbolManager ??= this.findManagerInParents();
        this.symbolManager?.init();
        this.buildFrameIdxToSymbolId();

        for (let i = 0; i < this.posList.length; i++) {
            const node = new Node(`cell_${i}`);
            node.layer = this.node.layer; // 坑 #3：程式建出來的節點 layer 不會自動修正，Camera 遮罩會整個擋掉
            const ui = node.addComponent(UITransform);
            ui.setContentSize(this.cellSize.width, this.cellSize.height);
            ui.setAnchorPoint(0.5, 0.5);

            node.setPosition(this.posList[i].position);
            this.container.addChild(node);

            const cell = node.addComponent(SymbolCell);
            cell.setup(this.symbolManager, this);

            this.symbolNodes.push(node);
            this.symbolCells.push(cell);
            this.symbolOpacities.push(node.addComponent(UIOpacity));
            this.posIndexes.push(i);

            const stripIdx = (this.model.currentRng + i) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
        this.updateDrawOrder();
    }

    /**
     * 往上找最近的一顆 {@link SymbolImageManager}。
     *
     * Inspector 上那個欄位目前是有填的（SlotMachineView_1003.prefab 的五欄各有一筆
     * propertyOverride 指向根節點上的池子），這一支是保險：巢狀 prefab instance 的
     * propertyOverride 在重新套用 prefab、或把某一欄搬進搬出時很容易掉，掉了的症狀是整欄默默沒有
     * 任何符號。往上找一次就補回來，Inspector 的欄位留給「這一欄要用別顆池子」這種例外情況覆寫。
     *
     * Cocos 3.8 沒有 `getComponentInParent`，所以自己走一遍父鏈。
     *
     * @returns 找到的池子；整條父鏈都沒有時為 null。
     */
    private findManagerInParents(): SymbolImageManager {
        for (let node = this.node.parent; node; node = node.parent) {
            const manager = node.getComponent(SymbolImageManager);
            if (manager) return manager;
        }
        console.warn(`[ReelView_1003] ${this.node.name} 找不到 SymbolImageManager，這一欄不會有任何符號`);
        return null!;
    }

    /**
     * 建立 `spriteFrames` 索引 → 符號 id 的對照表。
     *
     * 走訪本遊戲所有的符號 id（一般 1–9、scatter、wild，以及金牌 101–109），用 `SlotGameDefinition`
     * 問出它的圖名，再回頭查 `spriteFrames` 裡的位置。
     *
     * **金牌一定要納入。** 它有自己的一組圖（`H1_g` 這種底牌圖名加 `_g`）也有自己的 prefab，納入之後金牌 id
     * 就能跟著 strip 流動，掉落途中租到的直接是 `Symbol_XX_Golden`；不納入的話只能等落地再補旗標，
     * 玩家會看到牌落下時是一般牌、落定才變金。
     */
    private buildFrameIdxToSymbolId(): void {
        this.frameIdxToSymbolId = new Array(this.spriteFrames.length).fill(-1);

        const ids: number[] = [];
        for (let id = SYMBOL_IDS.normalMin; id <= SYMBOL_IDS.normalMax; id++) ids.push(id);
        ids.push(SYMBOL_IDS.scatter, SYMBOL_IDS.wild);
        for (let id = SYMBOL_IDS.normalMin; id <= SYMBOL_IDS.normalMax; id++) ids.push(goldenSymbolIdOf(id));

        for (const id of ids) {
            const frameName = SLOT_GAME_DEFINITION.symbols.frameName(id);
            const idx = this.frameIdxByName(frameName);
            if (idx < 0) {
                console.warn(`[ReelView_1003] spriteFrames 裡找不到 ${frameName}（symbolId=${id}），這個符號不會顯示`);
                continue;
            }
            this.frameIdxToSymbolId[idx] = id;
        }
    }

    /**
     * 取某個格子的 {@link SymbolCell}。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @returns 對應的 cell；索引越界時為 null。
     */
    private cellAt(symbolIdx: number): SymbolCell | null {
        return this.symbolCells[symbolIdx] ?? null;
    }

    /**
     * 取目前停在某個可見列上的 {@link SymbolCell}。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @returns 對應的 cell；那一列沒有格子時為 null。
     */
    private cellAtRow(row: number): SymbolCell | null {
        const idx = this.symbolIdxAtRow(row);
        return idx < 0 ? null : this.cellAt(idx);
    }

    /**
     * 找出目前停在某個可見列上的符號節點。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @returns 符號節點在這一欄的索引；找不到時為 -1。
     */
    private symbolIdxAtRow(row: number): number {
        return this.findSymbolNodeAtPosIndex(row + this.rowToPosOffset);
    }

    /**
     * 後端的可視列 0 要落在 posList 的第幾格。
     *
     * 緩衝格之外再讓開上緣的裝飾格——兩側欄多出來的上下兩個半格不吃後端資料，
     * 不讓開的話後端那四列會整欄往上錯一格，現有的格位全部位移。
     */
    protected override get rowToPosOffset(): number {
        return ReelView_1003.BUFFER_SLOTS + this.decorativeEdgeRows;
    }

    /** 這一欄真正吃後端資料的列數（可視列數扣掉上下兩圈裝飾格） */
    protected override get dataRowCount(): number {
        return Math.max(0, this.configuredVisibleRowCount - this.decorativeEdgeRows * 2);
    }

    /**
     * 把下緣的裝飾格換成輪帶上「資料段再往下一格」的符號。
     *
     * 後端未來會給 5/6/6/6/5 的盤面，多的那一列在**上方**，所以上緣的裝飾格有資料可吃；
     * 左下與右下這兩格後端不會給，只能自己從輪帶撈。取 `strip[rowToPosOffset + dataRowCount]`
     * 是因為 {@link patchVisibleStrip} 只會覆寫 `rowToPosOffset` 起算的資料段，
     * 緊接其後的那一格仍是原始輪帶內容——也就是「這一欄繼續往下轉會出現什麼」。
     *
     * 連鎖補牌不會碰到下緣裝飾格（它在所有資料格之下，沒有東西會落到它身上），
     * 所以每次補完要自己刷一次，否則整場 spin 都會是同一個符號。
     */
    private refreshBottomDecorativeCell(): void {
        if (this.decorativeEdgeRows <= 0 || this.strip.length === 0) return;

        const posIdx = this.rowToPosOffset + this.dataRowCount;
        const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
        if (symIdx < 0) return;

        this.setSymbolDisplay(symIdx, this.strip[posIdx % this.strip.length]);
    }

    /**
     * 連鎖補牌：交給 base 跑完，再補刷下緣的裝飾格。
     *
     * @param toMapCol 補牌後這一欄由上而下的 frameIdx。
     * @param elimRows 這一輪被消除的可視列。
     * @param fillTime 掉落時長（秒）。
     * @param dropRowDelay 逐列延遲（秒）。
     * @param onFirstLanded 第一顆落地時的回呼。
     * @param fillEase 補間曲線。
     * @returns 補牌演出結束後 resolve。
     */
    override async cascadeFill(
        toMapCol: number[],
        elimRows: number[],
        fillTime: number,
        dropRowDelay: number,
        onFirstLanded?: () => void,
        fillEase: TweenEasing = 'quadIn'
    ): Promise<void> {
        await super.cascadeFill(toMapCol, elimRows, fillTime, dropRowDelay, onFirstLanded, fillEase);
        this.refreshBottomDecorativeCell();
    }

    /**
     * 可視格的 posList 索引，由下往上排列（整欄掉落與補牌都從最底下那格開始）。
     *
     * @returns posList 索引陣列，不含上下緩衝格。
     */
    private visiblePosIndexesBottomUp(): number[] {
        const order: number[] = [];
        for (let i = this.posList.length - 1 - ReelView_1003.BUFFER_SLOTS; i >= ReelView_1003.BUFFER_SLOTS; i--) order.push(i);
        return order;
    }

    /**
     * 把某一格換成指定的符號，並清掉上一個符號留下的附加狀態。
     *
     * 外部仍以 frameIdx 溝通（base 的輪帶邏輯與 CascadeReelsTask 都是），這裡翻譯成符號 id 交給
     * {@link SymbolCell}。換符號時一律先清金牌與中獎層的強制狀態——否則上一顆的金色或中獎演出
     * 會殘留在後來掉進這一格的一般牌上。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @param stripIdx 要顯示的圖在 spriteFrames 裡的索引。
     */
    override setSymbolDisplay(symbolIdx: number, stripIdx: number): void {
        const cell = this.cellAt(symbolIdx);
        if (!cell) return;

        cell.clearState(SymbolStateLevel.Win);
        cell.clearState(SymbolStateLevel.High);

        const symbolId = this.frameIdxToSymbolId[stripIdx] ?? -1;
        if (symbolId < 0) {
            console.warn(`[ReelView_1003] frameIdx=${stripIdx} 對不到任何符號 id，該格不會換圖`);
            return;
        }
        cell.setSymbolId(symbolId);
        this.placeCell(symbolIdx);
    }

    /** 沒有 spine 可以對齊、也沒有覆寫值時的消除時長（秒），沿用改版前的預設 */
    private static readonly STATIC_ERASE_TIME = 0.3;

    /**
     * 消除爆破：先播 {@link playEraseFx} 的演出，播完再交給 base 做收尾記帳。
     *
     * base 的 `explode()` 仍然要跑——它負責把節點的 opacity 歸零、scale 復位，讓格子能重複使用。
     * 這裡用 `explodeTime` 0 呼叫，只取那份記帳、不再播一次縮小動畫；壓整格時 scale 的復位也靠它。
     *
     * @param rows 要消除的可見列。
     * @param explodeTime 覆寫的演出時長（秒）；0 表示依動畫原長，見 {@link playEraseFx}。
     * @returns 全部消除演出結束後 resolve。
     */
    override async explode(rows: number[], explodeTime: number): Promise<void> {
        await this.playEraseFx(rows, explodeTime);
        await super.explode(rows, 0);

        // 爆破結束後把 Erase 讓出來，格子回到由輪軸旗標推算的預設狀態，才能被補牌重複使用
        for (const row of rows) this.cellAtRow(row)?.clearState(SymbolStateLevel.High);
    }

    /**
     * 治具：這一欄所有可玩列各演一次 Erase，播完還原成原本的盤面——不消除、不記帳、不補牌。
     *
     * 只涵蓋可玩列（{@link dataRowCount}），兩側欄上下的裝飾半格不算：它們不吃後端資料，正式
     * 流程裡從來不會被消除。播完逐格讓出 Erase 並立刻 flush：Erase 那顆顯示物件回收時會自己還原
     * `scaleTarget` 的縮放；退回壓整格的那幾格（沒接 `scaleTarget` 的 scatter／wild）則在這裡把
     * 外殼縮放復位，跟 base `explode()` 的 `hide()` 一樣復位成 1。
     *
     * @param explodeTime 覆寫的演出時長（秒），與正式消除相同的換算方式；0 表示依動畫原長。
     * @returns 演完並還原後 resolve。
     */
    async previewErase(explodeTime: number): Promise<void> {
        const rows = Array.from({ length: this.dataRowCount }, (_, row) => row);
        await this.playEraseFx(rows, explodeTime);

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            cell?.clearState(SymbolStateLevel.High);
            cell?.flush();
            const symIdx = this.symbolIdxAtRow(row);
            if (symIdx >= 0) this.symbolNodes[symIdx].setScale(1, 1, 1);
        }
    }

    /**
     * 消除演出本體：把指定列切到 {@link SymbolState.Erase}，spine 與圖面壓扁一起播完。只負責演出，
     * 不讓出 Erase、不做 base 的收尾記帳——接下來是補牌還是還原，由呼叫端決定。
     *
     * 改版前是逐格問 `NgSymbol.hasEliminateFx()`「這格有沒有特效可播」，有才播 spine、沒有就退回
     * base 的縮小 tween。現在不需要那個分岔：`Erase` 狀態缺項時物件池會自動 fallback 回 `Normal`
     * （見 `SymbolImageManager.registerPrefab`），呼叫端一律當成有特效處理即可。
     *
     * **時長預設來自美術**：整段演出等於最長那一軌的動畫原長（`symbol_frame` 約 1.03 秒），spine 以
     * 原速播，每一軌都完整播完。`explodeTime` 給正數時是覆寫值：timeScale = 動畫原長 ÷ `explodeTime`，
     * 所有軌與壓扁一起等比縮放到那個秒數，相對節奏不變。快轉／急速轉不經過這裡——它們走全域的
     * 播放倍率（`setDirectorSpeedFactor`），spine 與補間會一起變快。
     *
     * 同一時間把符號圖面的 `scale.x` 補間到 0，從橫向壓扁收掉，取代原本「爆破播完就瞬間不見」的
     * 處理。**壓扁與 spine 同時開始，時長等於 `scaleSyncSkeleton` 那一軌的動畫**（Erase 的 `symbol`
     * 約 0.5 秒）：圖面的動畫與壓扁是一起演的。壓扁的對象是顯示物件指定的 `scaleTarget`（Erase 底下
     * 的 `Symbol` 圖面），爆破的 spine 不跟著變形；沒指定時（含 Erase 缺項退回 Normal）才壓整格。
     * `scaleTarget` 的縮放由顯示物件回收時自己還原（見 `SymbolViewSpine.onReturn`）。
     *
     * 完全沒有 spine 可以對齊的格子（靜態圖），演出與壓扁都用 `explodeTime`，沒給就用
     * {@link STATIC_ERASE_TIME}。
     *
     * @param rows 要演出的可見列。
     * @param explodeTime 覆寫的演出時長（秒）；0 或負數表示依動畫原長。
     * @returns 每一格的 spine 與壓扁都結束後 resolve。
     */
    async playEraseFx(rows: number[], explodeTime: number): Promise<void> {
        const override = explodeTime > 0 ? Math.max(explodeTime, 0.05) : 0;
        const tasks: Promise<void>[] = [];

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            if (!cell) continue;
            cell.setState(SymbolState.Erase, SymbolStateLevel.High);
            // 先 flush 換到 Erase 那顆顯示物件（租借時 resetAni 會把 timeScale 歸 1），才讀得到它的動畫長度
            cell.flush();

            const animDuration = cell.getAnimDuration();
            const timeScale = animDuration > 0 && override > 0 ? animDuration / override : 1;
            if (timeScale !== 1) cell.setTimeScale(timeScale);
            const fxTime = animDuration > 0 ? animDuration / timeScale : override || ReelView_1003.STATIC_ERASE_TIME;
            const scaleDuration = cell.getScaleDuration();
            const scaleTime = scaleDuration > 0 ? scaleDuration / timeScale : fxTime;
            tasks.push(cell.playCurrentStateOnce(fxTime));

            const symIdx = this.symbolIdxAtRow(row);
            const target = cell.getScaleTarget() ?? (symIdx >= 0 ? this.symbolNodes[symIdx] : null);
            if (!target) continue;
            // 只壓 x，y／z 維持原值
            tasks.push(ReelView.tweenNodeTo(target, scaleTime, { scale: new Vec3(0, target.scale.y, target.scale.z) }));
        }

        await Promise.all(tasks);
    }

    /** 中獎符號爆炸前,對指定 row 的符號各播一次中獎演出的基準時長；
     *  timeScale 隨三段速的 winFx 時長縮放（同 explode 的做法） */
    private static readonly WIN_FX_BASE_TIME = 1.6;

    /**
     * 爆破前先對指定列各播一次中獎演出：切到 {@link SymbolState.WinAnimation}，等它播完。
     *
     * 狀態設在 {@link SymbolStateLevel.Win} 層——高於轉動邏輯的 `Reel` 層，所以不管輪軸當下
     * 在算什麼狀態都會被蓋過去；也因為只設這一層，中獎演出結束時只要 `clearState(Win)`
     * 就能乾淨退場，不影響別的系統設過的狀態。
     *
     * @param rows 中獎的可見列。
     * @param winFxTime 這一段的時長（秒），timeScale 依它縮放；預設用基準值。
     * @returns 全部播完後 resolve。
     */
    playWinFx(rows: number[], winFxTime = ReelView_1003.WIN_FX_BASE_TIME): Promise<void> {
        const duration = Math.max(winFxTime, 0.05);
        const speed = ReelView_1003.WIN_FX_BASE_TIME / duration;
        const promises: Promise<void>[] = [];

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            if (!cell) continue;
            cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
            cell.flush();
            cell.setTimeScale(speed);
            promises.push(cell.playCurrentStateOnce(duration));
        }

        return Promise.all(promises).then(() => undefined);
    }

    /**
     * 把某一列切到中獎狀態，供共用的 `SlotMachineView.playSymbolWins()` 連線演出路徑使用。
     *
     * 1003 自己的消除流程走的是 {@link playWinFx}，不經過這裡；這一支是為了讓那條共用路徑仍然
     * 可用而保留（見 `.docs/1003-symbol-system-gap-analysis.md` 第四節：那套框架目前沒接）。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @param _animName 保留參數，改版後動畫由 prefab 上的 `SymbolViewSpine` 決定。
     * @param loop 是否循環；false 時才會觸發 `onComplete`。
     * @param onComplete 播完的回呼。
     * @returns 有成功切到中獎狀態為 true；那一列沒有格子時為 false。
     */
    playWinAnim(row: number, _animName: string, loop: boolean = true, onComplete?: () => void): boolean {
        const cell = this.cellAtRow(row);
        if (!cell) return false;

        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();

        if (!loop && onComplete) {
            void cell.playCurrentStateOnce(ReelView_1003.WIN_FX_BASE_TIME).then(onComplete);
        }
        return true;
    }

    /**
     * DebugPanel「Symbol 縮放」呼叫，套用到這一欄目前所有的格子。
     *
     * @param scale 縮放倍率，1 為原始大小。
     */
    setSymbolScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setScaleMultiplier(scale);
    }

    /**
     * 調整這一欄所有格子的動畫播放速度。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setTimeScale(scale);
    }

    /**
     * 結束中獎演出：把 {@link SymbolStateLevel.Win} 層讓出來，格子自動回到預設狀態。
     *
     * 改版前是逐格把 spine 切回各自的 `*stop` 動畫（需要一張 `SPINE_STOP_ANIM` 對照表）；
     * 現在不需要——退出 `WinAnimation` 狀態時物件池會把中獎用的顯示物件收回去、換回 `Normal`
     * 那一顆，靜止外觀本來就是它。
     */
    stopAllWinAnims(): void {
        for (const cell of this.symbolCells) cell?.clearState(SymbolStateLevel.Win);
    }

    /**
     * 金牌翻面成 Wild：scaleX 1 → 0 → 1，中點換成 Wild。
     *
     * TODO(#5 美術整合)：正式動畫應為翻牌 spine，屆時整支換掉即可。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @param wildFrameIdx Wild 圖在 spriteFrames 裡的索引。
     * @returns 翻面播完後 resolve；找不到格子時立即 resolve。
     */
    playGoldenToWild(row: number, wildFrameIdx: number): Promise<void> {
        const idx = this.symbolIdxAtRow(row);
        const cell = this.cellAt(idx);
        const node = cell?.node;
        if (!cell || !node?.isValid) return Promise.resolve();

        const half = ReelView_1003.GOLDEN_FLIP_SEC / 2;
        const base = node.scale.clone();
        return new Promise<void>((resolve) => {
            tween(node)
                .to(half, { scale: new Vec3(0, base.y, base.z) }, { easing: 'quadIn' })
                .call(() => this.swapToWildFrame(idx, wildFrameIdx))
                .to(half, { scale: base }, { easing: 'quadOut' })
                .call(() => resolve())
                .start();
        });
    }

    /**
     * 翻牌到最薄的那一瞬間換符號：換成 Wild。
     *
     * 翻面的 tween 套在格子節點上而不是符號圖上——改版後符號圖是租來的、中途可能被換掉，
     * tween 的目標必須是那顆從頭到尾都在的常駐節點。
     *
     * @param idx 這一格在 symbolNodes 裡的索引。
     * @param wildFrameIdx Wild 圖在 spriteFrames 裡的索引。
     */
    private swapToWildFrame(idx: number, wildFrameIdx: number): void {
        const cell = this.cellAt(idx);
        if (!cell?.node?.isValid) return;
        this.setSymbolDisplay(idx, wildFrameIdx);
        cell.flush();
    }

    /**
     * 播 scatter 中獎演出。
     *
     * scatter 沒有專屬狀態——它的中獎演出跟一般符號一樣是 `WinAnimation`，差別只在資產不同，
     * 而資產差異已經由「每個符號一支 prefab」吸收掉了。
     *
     * @param row 可見列。
     */
    playScatterWin(row: number): void {
        const cell = this.cellAtRow(row);
        if (!cell) return;
        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();
    }

    /**
     * scatter 落定時的顯示。
     *
     * 改版後 scatter 的靜止外觀就是它自己 prefab 的 `Normal` 節點，落定時不需要另外切換任何
     * 東西，所以這支只保留空實作維持呼叫端相容。等 scatter 有專屬的落定演出時再填。
     *
     * @param _row 可見列（0 起算，由上往下）。
     */
    revealScatter(_row: number): void {
        // scatter 的靜止外觀即 Normal 狀態，落定不需額外處理
    }

    /**
     * 取某個格位的世界座標，飄分數字要用它定位。
     *
     * @param posIdx posList 的索引（可見列 + {@link ReelView_1003.BUFFER_SLOTS}）。
     * @returns 該格位的世界座標。
     */
    getCellWorldPosition(posIdx: number): Vec3 {
        return this.posList[posIdx].getWorldPosition();
    }

    /** 落地果凍效果（squash）的關鍵影格：scale 是每格相對 (1,1) 的目標值，intensity=1 時為原始美術數值 */
    private static readonly SQUASH_KEYFRAMES: { time: number; scale: [number, number]; easing: TweenEasing }[] = [
        { time: 0.11, scale: [1.45, 0.66], easing: 'quadOut' },
        { time: 0.12, scale: [0.8, 1.25], easing: 'quadOut' },
        { time: 0.08, scale: [1.25, 0.8], easing: 'quadOut' },
        { time: 0.09, scale: [0.9, 1.12], easing: 'quadOut' },
        { time: 0.08, scale: [1, 1], easing: 'sineOut' },
    ];

    /** DebugPanel「果凍效果」滑桿：0=關閉、1=原始美術數值、可調更誇張，下次 spin 生效；預設 0.8 */
    private squashIntensity: number = 0.8;

    /**
     * 設定落地果凍效果的強度，下次 spin 生效。
     *
     * @param intensity 0 = 關閉、1 = 原始美術數值，可以調更大。
     */
    setSquashIntensity(intensity: number): void {
        this.squashIntensity = intensity;
    }

    /**
     * 把果凍效果的關鍵影格接到既有的 tween 後面。
     *
     * @param t 要接續的 tween。
     * @returns 接好的 tween；強度為 0 時原樣回傳。
     */
    private landingSquash(t: Tween<Node>): Tween<Node> {
        if (this.squashIntensity <= 0) return t;
        for (const kf of ReelView_1003.SQUASH_KEYFRAMES) {
            const sx = 1 + (kf.scale[0] - 1) * this.squashIntensity;
            const sy = 1 + (kf.scale[1] - 1) * this.squashIntensity;
            t = t.to(kf.time, { scale: new Vec3(sx, sy, 1) }, { easing: kf.easing });
        }
        return t;
    }

    /**
     * 整欄清空：可視格全部往下掉出畫面。
     *
     * 掉落距離取該欄自己的可視列數（葫蘆型盤面每欄不同），耗時用重力反推而不是直接吃
     * clearTime，再疊上逐列漸快的 stagger 維持原本手感。
     *
     * @param clearTime 這一段的基準時長（秒）。
     * @param rowDelay 每一列之間的延遲（秒），預設 0.05。
     * @param clearEase 補間曲線，預設 quadIn。
     * @returns 整欄都掉完後 resolve。
     */
    override async tumbleClear(clearTime: number, rowDelay: number = 0.05, clearEase: TweenEasing = 'quadIn'): Promise<void> {
        const promises: Promise<void>[] = [];
        // 只清可視格，頭尾各 BUFFER_SLOTS 格緩衝在畫面外不需要演出
        const dropOrder = this.visiblePosIndexesBottomUp();

        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        // 不規則輪帶（如葫蘆型盤面）各欄可視列數可能不同，掉落距離取該欄自己的可視列數
        const boardHeight = cellHeight * this.visibleRowCount;
        // 物理式掉落：整批同樣掉出 boardHeight 這段距離，用重力反推的耗時取代固定 clearTime，
        // 每行仍保留原本的漸快 stagger 手感（0.75 + i*0.125）疊在物理耗時之上。
        const physicsClearTime = this.physicsFallDuration(boardHeight, this.cellHeightAbs(), clearTime);

        for (let i = 0; i < dropOrder.length; i++) {
            const posIdx = dropOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;
            const node = this.symbolNodes[symIdx];
            const opacity = this.symbolOpacities[symIdx];
            const targetY = this.posList[posIdx].position.y - boardHeight;

            const rowClearTime = physicsClearTime * (0.75 + i * 0.125);

            promises.push(
                ReelView.tweenNodeTo(node, rowClearTime, { position: new Vec3(0, targetY, 0) }, {
                    delay: i * rowDelay,
                    easing: clearEase,
                    onArrive: () => (opacity.opacity = 0),
                })
            );
        }
        await Promise.all(promises);
    }

    /**
     * 整欄填入新符號：從畫面上方掉下來，逐列落定。
     *
     * 落定期間會放行倍率球打雷（{@link onSymbolSettled}），cascade 的補牌則不會。
     *
     * @param newSymbolNames 要填入的符號名稱，由上往下。
     * @param fillTime 這一段的基準時長（秒）。
     * @param rowDelay 每一列之間的延遲（秒），預設 0.05。
     * @param onFirstLanded 該欄第一顆落定時呼叫一次，用來即時播停輪音。
     * @param fillEase 補間曲線，預設 quadIn。
     * @returns 整欄都落定後 resolve。
     */
    override async tumbleFill(newSymbolNames: string[], fillTime: number, rowDelay: number = 0.05, onFirstLanded?: () => void, fillEase: TweenEasing = 'quadIn'): Promise<void> {
        const cellHeight = this.posList[1].position.y - this.posList[2].position.y;
        const startY = this.posList[0].position.y + cellHeight * 2;
        const promises: Promise<void>[] = [];
        // 只填可視格；筆數必須等於 newSymbolNames 長度，否則 nameIdx 會取到 undefined
        const fillOrder = this.visiblePosIndexesBottomUp();

        for (let i = 0; i < fillOrder.length; i++) {
            const posIdx = fillOrder[i];
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0) continue;

            const nameIdx = fillOrder.length - 1 - i;
            const srcName = newSymbolNames[nameIdx];
            const imgName = srcName;
            let frameIdx = this.frameIdxByName(imgName);
            if (frameIdx < 0) {
                console.warn(
                    `[tumbleFill] no spriteFrame for name="${imgName}" (src="${srcName}"), sprite frames:`,
                    this.spriteFrames.map((f) => f?.name)
                );
                frameIdx = 0;
            }

            const targetY = this.posList[posIdx].position.y;

            this.setSymbolDisplay(symIdx, frameIdx);
            this.symbolOpacities[symIdx].opacity = 255;
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            this.symbolNodes[symIdx].setPosition(0, startY, 0);

            const node = this.symbolNodes[symIdx];
            // 物理式掉落：各行從同一個 startY 落到各自的 targetY，落下距離不同（越下面的格子
            // 掉得越遠），用重力反推耗時取代所有行套同一個固定 fillTime；落地前加一小段
            // 落地彈跳（appendLandingBounce）再接既有的縮放 squash（landingSquash）。
            const cellHeightAbs = this.cellHeightAbs();
            const physicsFillTime = this.physicsFallDuration(targetY - startY, cellHeightAbs, fillTime);
            promises.push(
                new Promise<void>((resolve) => {
                    Tween.stopAllByTarget(node);
                    const fallTween = tween(node)
                        .delay(i * rowDelay)
                        .to(physicsFillTime, { position: new Vec3(0, targetY, 0) }, { easing: fillEase })
                        .call(() => onFirstLanded?.()); // 到達 targetY
                    this.landingSquash(this.appendLandingBounce(fallTween, targetY, cellHeightAbs))
                        .call(() => {
                            this.onSymbolSettled(symIdx);
                            resolve();
                        })
                        .start();
                })
            );
        }
        await Promise.all(promises);
    }
}
