import { Button, Label, sp, tween, Tween, Vec3 } from "cc";
import StoreManager from "../store/StoreManager";
import { AUTOSPINSTATUSMAP, GAMESTOREMAP, GAMEVIEWMAP } from "../store/StoreMap";
import AppAudio from "../audio/AppAudio";
import { getLocalizedString } from "../i18n/LanguageData";
import EagleTracker from "../tracking/EagleTracker";
import TrackerMap from "../tracking/TrackerMap";
import { SlotMachineState } from "../reel/model/SlotMachineModel";
import type { SubscriptionBag } from "../events/SubscriptionBag";
import type { TypedEventBus } from "../events/TypedEventBus";
import { GAME_EVENT_TYPE, type GameRuntimeEvents } from "../events/GameRuntimeEventBus";

/**
 * BuyFeatureController（花錢直接買免費遊戲）
 *
 * 1001/1002 共用同一份邏輯，各遊戲透過 BuyFeatureDeps 注入自己的差異值
 * （音效 bundle 名稱、音效路徑、View 元件）。
 *
 * - 價格顯示：依押注 × 倍率（buy_random/buy_super 各自可由 setMultipliers 覆寫）
 *   算出花費金額並顯示，押注變動時自動更新。
 * - 購買流程：點按鈕 → 檢查機台狀態/餘額 → 開確認彈窗 → 確認則扣款觸發 spin，
 *   取消則還原狀態；全程埋 EagleTracker 事件。
 * - 按鈕閃爍提示（AB 測試用）：依伺服器下發的 ab_test_info 分組、已玩局數、
 *   餘額門檻決定是否閃爍；FLASH_ENABLED 目前關閉（Azen 2026-04-28 提的需求，
 *   下次實驗再打開）。
 */

/** BuyFeatureController 只需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export interface BuyFeatureView {
    buyRandomBtn?: Button | null;
    buyRandomPriceLabel?: Label | null;
    buySuperBtn: Button;
    buySuperPriceLabel?: Label | null;
    buyRandomFlashSpine?: sp.Skeleton | null;
    buySuperFlashSpine?: sp.Skeleton | null;
}

/** 各遊戲自己的 Buy Feature 音效素材路徑（EFFECTSMAP 的子集合），音效檔案放在各遊戲自己的 bundle 底下 */
export interface BuyFeatureEffects {
    BUY_POPUP: string;
    BUY_CHECK: string;
    BUY_CLOSE: string;
}

export interface BuyFeatureDeps {
    getViews: () => BuyFeatureView[];
    storeManager: StoreManager;
    getSlotState: () => SlotMachineState;
    stopWinAnimations: () => void;
    /** 傳給 AppAudio.getInstance() 的 bundle 名稱（各遊戲自己的 bundle，例如 '1001'/'1002'） */
    audioBundleName: string;
    effects: BuyFeatureEffects;
}

export class BuyFeatureController {
    pendingBuyFeatureId: string | null = null;
    pendingBuyFeatureCost: number = 0;

    private buyRandomMultiplier: number = 50;
    private buySuperMultiplier: number = 100;
    private pending: boolean = false;
    /** popup 開啟動畫期間鎖住 mask 點外取消，避免「按 buy 同時點空白」的 race */
    private isOpening: boolean = false;

    // AB test 閃爍特效狀態
    private flashActive: Record<string, boolean> = { buy_random: false, buy_super: false };
    /** 總開關：本週更新先關掉，下次實驗再打開（Azen 2026-04-28 提的需求） */
    private static readonly FLASH_ENABLED: boolean = false;
    // 閃爍門檻：玩過幾局沒進 feature 才觸發 + 餘額需 > bet × 對應倍率
    private static readonly FLASH_COUNT_THRESHOLD: Record<string, number> = {
        buy_random: 50,
        buy_super: 100,
    };
    private static readonly FLASH_BALANCE_MULTIPLIER: Record<string, number> = {
        buy_random: 50,
        buy_super: 100,
    };

    private static readonly ANIM_MAP: Record<string, string> = {
        buy_random: "buyonefeature/buyonefeature",
        buy_super: "buytriplefeature/buytriplefeature",
    };

    // 美術提供的閃爍 animation 名稱（每個按鈕各自一個）
    private static readonly FLASH_ANIM_NAME: Record<string, string> = {
        buy_random: "buy_feature_btn",
        buy_super: "triple_feature_btn",
    };

    /**
     * @param deps 取得 View、store、轉輪狀態與音效設定的依賴集合。
     */
    constructor(private deps: BuyFeatureDeps) { }

    /** 餘額是 bet 的幾倍（規格：balance(餘額倍數)）— 取兩位小數方便 AB 統計分桶 */
    private computeBalanceMultiplier(): number {
        const balance = Number(this.deps.storeManager.getModel("UserStore").balance) || 0;
        const bet = this.deps.storeManager.getModel("TemplateStore").betBalance || 0;
        if (bet <= 0) return 0;
        return Math.round((balance / bet) * 100) / 100;
    }

    /**
     * 設定兩種購買方式的價格倍率（相對於目前下注額）。
     *
     * @param random 隨機購買的倍率。
     * @param sup 超級購買的倍率。
     */
    setMultipliers(random: number, sup: number): void {
        this.buyRandomMultiplier = random;
        this.buySuperMultiplier = sup;
    }

    /**
     * 取得指定購買方式的價格倍率。
     *
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     * @returns 價格倍率。
     */
    getCostMultiplier(buyFeatureId: string): number {
        return buyFeatureId === "buy_random" ? this.buyRandomMultiplier : this.buySuperMultiplier;
    }

    /**
     * 清掉「玩家正在確認中的是哪一種購買」的暫存；流程中斷時呼叫。
     */
    clearPendingId(): void {
        this.pendingBuyFeatureId = null;
    }

    /**
     * 綁定所有 View 上的兩顆購買鈕，並把閃爍 spine 停在第一幀當靜態顯示。
     */
    bindButtons(): void {
        for (const v of this.deps.getViews()) {
            if (v.buyRandomBtn) v.buyRandomBtn.node.on(Button.EventType.CLICK, () => this.onBuyFeature("buy_random"), this);
            v.buySuperBtn.node.on(Button.EventType.CLICK, () => this.onBuyFeature("buy_super"), this);
        }
        // 兩個 spine 先停在第一幀當靜態顯示（之後條件達到才開始循環）
        this.initFlashIdle();
    }

    /**
     * 訂閱價格/閃爍會用到的 4 個 EventBus 事件，並立即套用一次目前值。
     * 呼叫端自己的 SubscriptionBag（1001 用繼承來的 subscriptions、1002 用自己的 eventSubscriptions）都相容。
     */
    bindEvents(eventBus: TypedEventBus<GameRuntimeEvents>, subscriptions: SubscriptionBag): void {
        subscriptions.add(eventBus.on(GAME_EVENT_TYPE.BET_BALANCE_CHANGED, () => {
            this.updatePrices();
            this.reevaluateFlash();
        }));
        subscriptions.add(eventBus.on(GAME_EVENT_TYPE.USER_BALANCE_CHANGED, () => {
            this.reevaluateFlash();
        }));
        subscriptions.add(eventBus.on(GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED, () => {
            this.reevaluateFlash();
        }));
        subscriptions.add(eventBus.on(GAME_EVENT_TYPE.GAME_INIT_EXTRA_CHANGED, () => {
            this.reevaluateFlash();
        }));
        this.updatePrices();
        this.reevaluateFlash();
    }

    /** 強制兩個 flash spine 停在各自 animation 的第一幀 */
    initFlashIdle(): void {
        if (!BuyFeatureController.FLASH_ENABLED) {
            // 完全隱藏 flash spine，只剩按鈕本身
            for (const id of ["buy_random", "buy_super"] as const) {
                for (const v of this.deps.getViews()) {
                    const spine = this.getFlashSpineForId(v, id);
                    if (spine) spine.node.active = false;
                }
            }
            return;
        }
        for (const id of ["buy_random", "buy_super"] as const) {
            const animName = BuyFeatureController.FLASH_ANIM_NAME[id];
            if (!animName) continue;
            for (const v of this.deps.getViews()) {
                const spine = this.getFlashSpineForId(v, id);
                if (!spine) continue;
                spine.node.active = true;
                spine.setAnimation(0, animName, false);
                spine.timeScale = 0;
            }
        }
    }

    /**
     * 依目前下注額重算兩顆購買鈕上的價格文字。下注額變動時要呼叫。
     */
    updatePrices(): void {
        const bet = this.deps.storeManager.getModel("TemplateStore").betBalance;
        const fmt = this.deps.storeManager.getGameStore().formatAmount;
        for (const v of this.deps.getViews()) {
            if (v.buyRandomPriceLabel) v.buyRandomPriceLabel.string = fmt(bet * this.buyRandomMultiplier);
            if (v.buySuperPriceLabel) v.buySuperPriceLabel.string = fmt(bet * this.buySuperMultiplier);
        }
    }

    /**
     * 依 ab_test_info + 當前餘額/押注決定 buy feature 按鈕要不要閃爍
     * 只有 A 組會套用，B 組永遠不閃
     */
    updateFlashFx(abTestInfo: any, balance: number, bet: number): void {
        if (!BuyFeatureController.FLASH_ENABLED) {
            this.stopFlash("buy_random");
            this.stopFlash("buy_super");
            return;
        }
        const bf = abTestInfo?.buy_feature;
        if (!bf || bf.group !== "A") {
            this.stopFlash("buy_random");
            this.stopFlash("buy_super");
            return;
        }
        const count = Number(bf.count) || 0;
        for (const id of ["buy_random", "buy_super"] as const) {
            const countThreshold = BuyFeatureController.FLASH_COUNT_THRESHOLD[id];
            const balanceThreshold = bet * BuyFeatureController.FLASH_BALANCE_MULTIPLIER[id];
            const shouldFlash = count > countThreshold && balance > balanceThreshold;
            if (shouldFlash) this.startFlash(id);
            else this.stopFlash(id);
        }
    }

    /** 從最新的 spinData / initExtra 抓 ab_test_info + 目前餘額/押注，重新評估閃爍條件 */
    reevaluateFlash(): void {
        const gameStore = this.deps.storeManager.getGameStore();
        const spin = gameStore.spinData as any;
        const init = gameStore.initExtra as any;
        const abTestInfo = spin?.ab_test_info ?? init?.ab_test_info ?? null;
        const balance = Number(this.deps.storeManager.getModel("UserStore").balance) || 0;
        const bet = this.deps.storeManager.getModel("TemplateStore").betBalance;
        this.updateFlashFx(abTestInfo, balance, bet);
    }

    /**
     * 取得指定 View 上對應這種購買方式的按鈕。
     *
     * @param v 目標 View。
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     * @returns 對應的按鈕；該 View 沒有這顆時是 null。
     */
    private getBtnForId(v: BuyFeatureView, buyFeatureId: string): Button | null {
        return buyFeatureId === "buy_random" ? v.buyRandomBtn : v.buySuperBtn;
    }

    /**
     * 取得指定 View 上對應這種購買方式的閃爍 spine。
     *
     * @param v 目標 View。
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     * @returns 對應的 spine；該 View 沒有時是 null。
     */
    private getFlashSpineForId(v: BuyFeatureView, buyFeatureId: string): sp.Skeleton | null {
        return buyFeatureId === "buy_random" ? v.buyRandomFlashSpine : v.buySuperFlashSpine;
    }

    /**
     * 開始播某顆購買鈕的閃爍循環（餘額足夠時的提示）。已經在閃就不重播。
     *
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     */
    private startFlash(buyFeatureId: string): void {
        if (this.flashActive[buyFeatureId]) return;
        this.flashActive[buyFeatureId] = true;
        const animName = BuyFeatureController.FLASH_ANIM_NAME[buyFeatureId];
        for (const v of this.deps.getViews()) {
            const spine = this.getFlashSpineForId(v, buyFeatureId);
            if (spine && animName) {
                spine.node.active = true;
                spine.timeScale = 1;
                spine.setAnimation(0, animName, true);
                continue;
            }
            // fallback：沒綁 spine 就用 tween（可視化一下還有沒有連動）
            const btn = this.getBtnForId(v, buyFeatureId);
            if (!btn) continue;
            const node = btn.node;
            Tween.stopAllByTarget(node);
            tween(node)
                .to(0.35, { scale: new Vec3(1.2, 1.2, 1) }, { easing: 'sineInOut' })
                .to(0.35, { scale: new Vec3(1, 1, 1) }, { easing: 'sineInOut' })
                .union()
                .repeatForever()
                .start();
        }
    }

    /**
     * 停掉某顆購買鈕的閃爍，並凍在第一幀當靜態顯示。
     *
     * 凍在第一幀而不是關掉節點，是因為這組 spine 沒有另外做 idle 動畫，
     * 直接關掉按鈕會少一層圖。
     *
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     */
    private stopFlash(buyFeatureId: string): void {
        if (!this.flashActive[buyFeatureId]) return;
        this.flashActive[buyFeatureId] = false;
        const animName = BuyFeatureController.FLASH_ANIM_NAME[buyFeatureId];
        for (const v of this.deps.getViews()) {
            const spine = this.getFlashSpineForId(v, buyFeatureId);
            if (spine && animName) {
                // 凍在 animation 第一幀當靜態顯示（沒 idle animation 的 fallback）
                spine.node.active = true;
                spine.setAnimation(0, animName, false);
                spine.timeScale = 0;
            }
            // 也清掉 tween fallback（避免切換過程殘留）
            const btn = this.getBtnForId(v, buyFeatureId);
            if (!btn) continue;
            Tween.stopAllByTarget(btn.node);
            btn.node.setScale(1, 1, 1);
        }
    }

    /**
     * 按下購買鈕：擋掉不該進來的時機（轉輪不在閒置、自動轉中、已有流程在跑），
     * 埋點之後開啟確認彈窗。
     *
     * @param buyFeatureId 'buy_random' 或 'buy_super'。
     * @returns 彈窗開啟之後 resolve。
     */
    private async onBuyFeature(buyFeatureId: string): Promise<void> {
        if (this.deps.getSlotState() !== SlotMachineState.IDLE) return;
        if (this.deps.storeManager.getGameStore().autoSpinStatus === AUTOSPINSTATUSMAP.ON) return;
        if (this.pending) return;
        if (this.pendingBuyFeatureCost > 0) return;

        EagleTracker.trackerEvent(
            buyFeatureId === "buy_random" ? TrackerMap.BUY_RANDOM_CLICK : TrackerMap.BUY_TRIPLE_CLICK,
        );

        AppAudio.getInstance(this.deps.audioBundleName).playEffect(this.deps.effects.BUY_POPUP);
        this.pendingBuyFeatureId = buyFeatureId;
        this.isOpening = true;
        setTimeout(() => { this.isOpening = false; }, 600);

        const prefix = BuyFeatureController.ANIM_MAP[buyFeatureId];
        if (!prefix) return;

        const bet = this.deps.storeManager.getModel("TemplateStore").betBalance;
        const multiplier = this.getCostMultiplier(buyFeatureId);
        const amountStr = this.deps.storeManager.getGameStore().formatAmount(bet * multiplier);

        this.deps.storeManager.getViewStore().setGameViewName(GAMEVIEWMAP.BUYFEATUREPOPUP);
        this.deps.storeManager.getGameStore().playBuyFeature(
            prefix, amountStr, multiplier,
            () => this.onConfirm(),
            () => this.onCancel(),
        );
    }

    /**
     * 玩家在確認彈窗按下確認：埋點、關窗，然後送出購買那一轉。
     *
     * @returns 整段流程跑完之後 resolve。
     */
    private async onConfirm(): Promise<void> {
        if (this.pending) return;
        this.pending = true;
        AppAudio.getInstance(this.deps.audioBundleName).playEffect(this.deps.effects.BUY_CHECK);
        const buyFeatureId = this.pendingBuyFeatureId;
        if (!buyFeatureId) { this.pending = false; return; }
        EagleTracker.trackerEvent(TrackerMap.FEATURE_BUY_CURRENCY, {
            currency_type: buyFeatureId,
        });
        const balanceMultiplier = this.computeBalanceMultiplier();
        EagleTracker.trackerEvent(
            buyFeatureId === "buy_random" ? TrackerMap.BUY_RANDOM_CHECK : TrackerMap.BUY_TRIPLE_CHECK,
            { balance: balanceMultiplier },
        );

        const bet = this.deps.storeManager.getModel("TemplateStore").betBalance;
        const multiplier = this.getCostMultiplier(buyFeatureId);
        const cost = bet * multiplier;
        if (Number(this.deps.storeManager.getModel("UserStore").balance) < cost) {
            this.deps.storeManager.getViewStore().showStoreAlertView("", getLocalizedString("1102"));
            this.pending = false;
            return;
        }

        await this.deps.storeManager.getGameStore().closeBuyFeature();
        this.deps.storeManager.getViewStore().setDeleteViewName('buyFeaturePopup');
        this.deps.stopWinAnimations();
        this.deps.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.SPIN_START);
        this.pending = false;
    }

    /**
     * 玩家在確認彈窗按下取消：關窗並清掉暫存的購買種類。
     *
     * 開窗動畫還在跑時直接略過——那段期間的點擊是誤觸，
     * 真的讓它關掉會跟開窗動畫打架。
     *
     * @returns 關窗之後 resolve。
     */
    private async onCancel(): Promise<void> {
        if (this.isOpening) return;
        if (this.pending) return;

        AppAudio.getInstance(this.deps.audioBundleName).playEffect(this.deps.effects.BUY_CLOSE);
        const buyFeatureId = this.pendingBuyFeatureId;
        this.pendingBuyFeatureId = null;
        this.pending = false;

        if (buyFeatureId) {
            const balanceMultiplier = this.computeBalanceMultiplier();
            EagleTracker.trackerEvent(
                buyFeatureId === "buy_random" ? TrackerMap.BUY_RANDOM_CANCEL : TrackerMap.BUY_TRIPLE_CANCEL,
                { balance: balanceMultiplier },
            );
        }

        await this.deps.storeManager.getGameStore().closeBuyFeature();
        this.deps.storeManager.getViewStore().setDeleteViewName('buyFeaturePopup');
    }
}
