import { _decorator, Component } from 'cc';
import { Logger } from '../utils/Logger';
const { ccclass } = _decorator;

/**
 * UI 元件的共用基底：每個實例自帶一個以類別名稱為 tag 的 Logger。
 *
 * 從 1001 複製（2026-09-22），內容保持一致。
 */
@ccclass('1003/BaseUIComponent')
export class BaseUIComponent extends Component {
    public static readonly PROPERTY_NODE_NAME = 'Property';
    public log = new Logger(this.constructor.name);
}
