// /**
// * AppStore
// * 原生替代 KYCocosSDK/DesignPatterns/Mobx/KYStore.ts，方法簽名 1:1 對應，
// * 供逐步替換 import 路徑使用，KYCocosSDK 內檔案本身不受影響。
// *
// * mobx 移除計劃：改用純 class + plain Map，不再是 mobx-keystone Model / ObjectMap。
// * 註冊的 model 只要有 $modelType 欄位即可（不論是否仍為 mobx-keystone Model），
// * 所以現有各 Store 逐一遷移期間可以照舊透過 registerModel/getModel 使用。
// */

import { assert } from "cc";
export type BaseModelType = { $modelType: string };

export default class AppStore {
    /** 目前唯一的 AppStore 實例（由 StoreManager 建立）。
     *  取代原本 mobx-keystone getRootStore(this) 的用法——
     *  models 改成 plain Map 後已經不在 keystone tree 裡，
     *  SlotGameStore.spinCheck() 等處改用這個 static getter 取得 kystore。 */
    private static current: AppStore | null = null;
    /**
     * 目前作用中的 AppStore。
     *
     * @returns AppStore 實體；還沒建立時是 null。
     */
    public static getCurrent(): AppStore | null {
        return AppStore.current;
    }

    public readonly models = new Map<string, BaseModelType>();

    /**
     * 把自己登記成目前作用中的 AppStore。
     */
    constructor() {
        AppStore.current = this;
    }

    /**
     * 依 model 自己的 `$modelType` 把它放進 registry。
     *
     * @param model 要註冊的 model。
     * @throws model 沒有 `$modelType` 時斷言失敗。
     */
    public registerModel(model: BaseModelType): void {
        assert(!!model.$modelType, "Invalid model");
        this.models.set(model.$modelType, model);
    }
    /**
     * 把 model 從 registry 移除。
     *
     * @param model 要移除的 model。
     * @throws model 沒有 `$modelType` 時斷言失敗。
     */
    public unregisterModel(model: BaseModelType): void {
        assert(!!model.$modelType, "Invalid model");
        this.models.delete(model.$modelType);
    }

    /**
     * 依完整 key（含 `store/` 前綴）取出 registry 裡的 model。
     *
     * @param key model 的 `$modelType`。
     * @returns 對應的 model；沒註冊過時是 undefined。
     */
    public getModel<T = BaseModelType>(key: string): T | undefined {
        return this.models.get(key) as T | undefined;
    }
}
