import { _decorator, Node, sp, Tween, Vec3 } from 'cc';
import { SymbolView } from './SymbolView';
import { trySetAnimation, tryClearAnimation } from '../../utils/SpineSafe';

const { ccclass, property } = _decorator;

/**
 * 跟主軌同時播放的一支額外 Skeleton，以及它自己的播放設定。
 *
 * 純資料類別（不是 Component），序列化進 prefab 時 `__type__` 是 `@ccclass` 名稱，
 * 不是壓縮過的腳本 uuid（entry docs/agent-pitfalls.md 坑 #40）。
 */
@ccclass('1003/SymbolSpineTrack')
export class SymbolSpineTrack {
    @property({ type: sp.Skeleton, tooltip: '要一起播的 Skeleton；留空的這一筆會被略過' })
    public skeleton: sp.Skeleton | null = null;

    @property({ tooltip: '租借時要播的動畫名稱' })
    public animName: string = 'animation';

    @property({ tooltip: '是否循環播放。只影響租借時的播放，playOnce 一律只播一次' })
    public loop: boolean = false;
}

/** 一次播放實際要用的設定：哪支 skeleton、播哪個動畫、是否循環 */
interface ResolvedTrack {
    skeleton: sp.Skeleton;
    anim: string;
    loop: boolean;
}

/**
 * Spine 版的顯示層：租出去時播動畫，回收時清掉軌道。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §6（顯示技術轉接器）。
 * 邏輯層完全感覺不到自己租到的是 Sprite 版還是這一版。
 *
 * 一個狀態可以同時播好幾支 Skeleton：{@link skeleton} 是主軌，{@link extraTracks} 是跟它一起播的
 * 其他軌，租借、回收、調速、播一次都對全部一起作用。主軌沿用單一欄位而不是併進陣列，是為了讓
 * 既有 prefab 上存的 `skeleton`／`animName`／`loop` 不必搬遷。
 *
 * 用在 `WinAnimation`（主軌 `symbol_win` 火焰框）、`Erase`（主軌 `symbol_frame` 爆破，額外軌
 * `symbol` 符號本體的 `normal`／`golden`）、以及素材到位後的 `symbol_h`／`symbol_l` 符號動畫。
 */
@ccclass('1003/SymbolViewSpine')
export class SymbolViewSpine extends SymbolView {
    @property({ type: sp.Skeleton, tooltip: '主軌：實際播動畫的 Skeleton；主軌與額外軌都留空時這顆物件等同靜態圖' })
    public skeleton: sp.Skeleton = null!;

    @property({ tooltip: '主軌租借時要播的動畫名稱' })
    public animName: string = 'animation';

    @property({ tooltip: '主軌是否循環播放。中獎中的常駐演出勾起來，一次性爆破不要勾' })
    public loop: boolean = false;

    @property({ type: [SymbolSpineTrack], tooltip: '跟主軌同時播放的其他 Skeleton，各自設定動畫名與是否循環' })
    public extraTracks: SymbolSpineTrack[] = [];

    @property({ type: Node, tooltip: '消除時要壓扁的節點（例如 Erase 底下的 Symbol 圖面）；留空時壓扁整格' })
    public scaleTarget: Node | null = null;

    @property({ type: sp.Skeleton, tooltip: '壓扁補間的時長跟這支 Skeleton 要播的動畫一樣長（例如 Erase 的 symbol），兩者一起演；留空時改看下面的骨架資料' })
    public scaleSyncSkeleton: sp.Skeleton | null = null;

    @property({ type: sp.SkeletonData, tooltip: '沒有可對齊的 Skeleton 時（例如 scatter／wild 身上沒有 symbol），壓扁時長改用這份骨架資料裡的動畫長度' })
    public scaleSyncData: sp.SkeletonData | null = null;

    @property({ tooltip: '搭配上面骨架資料使用的動畫名稱（例如 normal）；兩者都留空時壓扁跟最長那一軌一樣長' })
    public scaleSyncAnim: string = '';

    /** {@link scaleTarget} 在 prefab 上的原始縮放，回收時還原用 */
    private readonly scaleTargetOrigin = new Vec3(1, 1, 1);

    /**
     * 每個符號的動畫名稱可能不同（例如 `symbol_h` 這份骨架裡 h1 叫 `God`、h2 叫 `h2`），
     * 所以租借時允許外部指定主軌的動畫；沒指定就用 {@link animName}。
     */
    private overrideAnim: string | null = null;

    /**
     * 指定這次租借主軌要播的動畫，必須在 {@link onRent} 之前呼叫。額外軌不受影響。
     *
     * @param anim 動畫名稱；傳 null 表示改用 prefab 上設定的 {@link animName}。
     */
    public setAnimOverride(anim: string | null): void {
        this.overrideAnim = anim;
    }

    /**
     * 建立當下先把每一軌都清乾淨，避免 prefab 存檔時殘留的預設動畫在節點一開就播出來；
     * 同時記下 {@link scaleTarget} 的原始縮放，回收時才知道要還原成多少。
     */
    protected override onInit(): void {
        for (const { skeleton } of this.resolveTracks()) tryClearAnimation(skeleton, 'SymbolViewSpine.onInit');
        if (this.scaleTarget) this.scaleTargetOrigin.set(this.scaleTarget.scale);
    }

    /**
     * 歸還：每一軌都停掉動畫、解除監聽並清空軌道，否則下次租出去會先閃一格上一次的最後畫面。
     *
     * {@link scaleTarget} 也要在這裡停掉補間、還原縮放：消除時被壓扁的是這顆物件自己的子節點，
     * 它會原樣回到物件池，不還原的話下次租出去圖面還停在 scale.x = 0，直接看不見。
     */
    public override onReturn(): void {
        for (const { skeleton } of this.resolveTracks()) {
            skeleton.setCompleteListener(null!);
            tryClearAnimation(skeleton, 'SymbolViewSpine.onReturn');
        }
        if (this.scaleTarget?.isValid) {
            Tween.stopAllByTarget(this.scaleTarget);
            this.scaleTarget.setScale(this.scaleTargetOrigin);
        }
        this.overrideAnim = null;
        super.onReturn();
    }

    /** @returns 有接且還有效的 {@link scaleTarget}；沒接時回 null，由呼叫端退回壓扁整格。 */
    public override getScaleTarget(): Node | null {
        return this.scaleTarget?.isValid ? this.scaleTarget : null;
    }

    /** 每一軌都從頭重播。動畫名不存在時 {@link trySetAnimation} 會吞掉例外並警告一次，不會中斷整條流程 */
    public override resetAni(): void {
        for (const { skeleton, anim, loop } of this.resolveTracks()) {
            skeleton.timeScale = 1;
            trySetAnimation(skeleton, anim, loop, 'SymbolViewSpine.resetAni');
        }
    }

    /**
     * 每一軌各播一次，等最長的那一軌播完才回呼。
     *
     * 只等切換成功的軌：動畫名不存在的那一軌不會有結束事件，把它算進去會讓這次播放只能靠
     * `SymbolCell` 的保底計時器收尾。所以監聽是在切完動畫、知道哪幾軌真的在播之後才掛；一軌都沒
     * 播起來（含完全沒接 skeleton）時立刻回呼，行為與基底一致。
     *
     * 只在 `trackIndex === 0` 時計數，避免其他軌道的結束事件誤觸。
     *
     * @param onComplete 全部播完時呼叫。
     */
    public override playOnce(onComplete: () => void): void {
        const playing: sp.Skeleton[] = [];
        for (const { skeleton, anim } of this.resolveTracks()) {
            skeleton.setCompleteListener(null!);
            if (trySetAnimation(skeleton, anim, false, 'SymbolViewSpine.playOnce')) playing.push(skeleton);
        }
        if (playing.length === 0) {
            onComplete();
            return;
        }

        let pending = playing.length;
        for (const skeleton of playing) {
            skeleton.setCompleteListener((entry) => {
                if (entry.trackIndex !== 0) return;
                skeleton.setCompleteListener(null!);
                pending--;
                if (pending === 0) onComplete();
            });
        }
    }

    /**
     * 每一軌一起調整播放速度，供三段速（一般／快速／turbo）縮放演出時長用。
     *
     * @param scale 倍率，1 為原速。
     */
    public override setTimeScale(scale: number): void {
        for (const { skeleton } of this.resolveTracks()) skeleton.timeScale = scale;
    }

    /**
     * 所有軌一起播時的總長：取最長那一軌在原速下的秒數。
     *
     * 各軌同時開始，所以總長是最大值而不是加總。查不到動畫的軌（動畫名不存在、資料還沒載好）
     * 算 0，不會讓結果變成 NaN。
     *
     * @returns 秒數；一軌都沒有可播的動畫時回 0。
     */
    public override getAnimDuration(): number {
        let longest = 0;
        for (const { skeleton, anim } of this.resolveTracks()) {
            longest = Math.max(longest, skeleton.findAnimation(anim)?.duration ?? 0);
        }
        return longest;
    }

    /**
     * 壓扁補間在原速下該多長，依序取第一個有設定的來源：
     *
     * 1. {@link scaleSyncSkeleton} 那一軌的動畫長度——用它要播的動畫名去查（主軌會吃
     *    {@link setAnimOverride}），所以這支 skeleton 必須是主軌或 {@link extraTracks} 其中之一。
     *    一般牌走這條，對齊自己身上的 `symbol`。
     * 2. {@link scaleSyncData} 裡 {@link scaleSyncAnim} 那支動畫的長度——身上沒有可對齊的 spine 時用，
     *    例如 scatter／wild 指向一般牌同一份 `symbol` 的 `normal`，美術改長度時會一起跟著變，
     *    不必另外抄一個秒數。
     * 3. 都沒設定（或接了一支不在軌道裡的 skeleton）時退回 {@link getAnimDuration}。
     *
     * @returns 秒數；指定的動畫不存在或骨架資料還沒載好時回 0。
     */
    public override getScaleDuration(): number {
        const sync = this.scaleSyncSkeleton;
        const track = sync?.isValid ? this.resolveTracks().find((t) => t.skeleton === sync) : undefined;
        if (track) return track.skeleton.findAnimation(track.anim)?.duration ?? 0;

        if (this.scaleSyncData && this.scaleSyncAnim) {
            return this.scaleSyncData.getRuntimeData(true)?.findAnimation(this.scaleSyncAnim)?.duration ?? 0;
        }
        return this.getAnimDuration();
    }

    /**
     * 列出要一起播的所有軌：主軌在前，額外軌依序在後。
     *
     * 沒接 skeleton 的、已銷毀的、以及重複出現的 skeleton 都會被略過——同一支掛兩次的話，
     * {@link playOnce} 會為一個只會來一次的結束事件等兩次。主軌的動畫名吃 {@link setAnimOverride}，
     * 額外軌一律用自己的設定。
     *
     * @returns 去重後的播放清單；一軌都沒接時為空陣列。
     */
    private resolveTracks(): ResolvedTrack[] {
        const out: ResolvedTrack[] = [];
        const seen = new Set<sp.Skeleton>();
        const add = (skeleton: sp.Skeleton | null, anim: string, loop: boolean): void => {
            if (!skeleton?.isValid || seen.has(skeleton)) return;
            seen.add(skeleton);
            out.push({ skeleton, anim, loop });
        };

        add(this.skeleton, this.overrideAnim ?? this.animName, this.loop);
        for (const track of this.extraTracks) {
            if (track) add(track.skeleton, track.animName, track.loop);
        }
        return out;
    }
}
