import { sys } from "cc";
import { BASE_EVENT_ID, BASE_EVENT_TYPE, baseRuntimeEventBus } from "../events/BaseRuntimeEventBus";

export class SettingStore {
    private _musicVolume: number = Number(sys.localStorage.getItem("music") ?? 1);
    /**
     * 音樂音量（0～1）。
     *
     * @returns 音量。
     */
    get musicVolume(): number { return this._musicVolume; }
    /**
     * 設定音樂音量並發 MUSIC_VOLUME_CHANGED。只改記憶體，不寫進 localStorage。
     *
     * 要一併持久化請用 setMusicVolumeStore()。
     *
     * @param value 音量（0～1）。
     */
    setMusicVolume(value: number): void {
        this._musicVolume = value;
        baseRuntimeEventBus.emit(BASE_EVENT_TYPE.MUSIC_VOLUME_CHANGED, {
            eventId: BASE_EVENT_ID.MUSIC_VOLUME_CHANGED,
            musicVolume: value,
        });
    }

    private _soundVolume: number = Number(sys.localStorage.getItem("sound") ?? 1);
    /**
     * 音效音量（0～1）。
     *
     * @returns 音量。
     */
    get soundVolume(): number { return this._soundVolume; }
    /**
     * 設定音效音量並發 SOUND_VOLUME_CHANGED。只改記憶體，不寫進 localStorage。
     *
     * 要一併持久化請用 setSoundVolumeStore()。
     *
     * @param value 音量（0～1）。
     */
    setSoundVolume(value: number): void {
        this._soundVolume = value;
        baseRuntimeEventBus.emit(BASE_EVENT_TYPE.SOUND_VOLUME_CHANGED, {
            eventId: BASE_EVENT_ID.SOUND_VOLUME_CHANGED,
            soundVolume: value,
        });
    }

    private _progress: number = 0;
    /**
     * 載入進度（0～1）。
     *
     * @returns 進度。
     */
    get progress(): number { return this._progress; }
    /**
     * 更新載入進度。
     *
     * @param value 進度（0～1）。
     */
    setProgress(value: number): void { this._progress = value; }

    /**
     * 設定音樂音量並寫進 localStorage，下次進遊戲會沿用。
     *
     * @param value 音量（0～1）。
     */
    public setMusicVolumeStore(value: number): void {
        this.setMusicVolume(value);
        sys.localStorage.setItem("music", value?.toString() ?? "");
    }

    /**
     * 設定音效音量並寫進 localStorage，下次進遊戲會沿用。
     *
     * @param value 音量（0～1）。
     */
    public setSoundVolumeStore(value: number): void {
        this.setSoundVolume(value);
        sys.localStorage.setItem("sound", value?.toString() ?? "");
    }
}
