import { _decorator, Asset, Component, game, native, sys } from 'cc';
import GameConfigManager from '../config/GameConfigManager';
import { getSubGameData } from '../types/SubGameData';

const { ccclass } = _decorator;

export enum NativeUpdateResult {
    UpToDate,
    Restarting
}

const SEARCH_PATHS_STORAGE_KEY = 'native_bundle_update_search_paths';

/** 版本號用點分隔數字比較 例如 1.0.2 對 1.0.10 */
function compareVersion(versionA: string, versionB: string): number {
    const a = versionA.split('.').map(Number);
    const b = versionB.split('.').map(Number);
    for (let i = 0; i < Math.max(a.length, b.length); i++) {
        const diff = (a[i] ?? 0) - (b[i] ?? 0);
        if (diff !== 0) return diff;
    }
    return 0;
}

/**
 * NativeBundleUpdater
 *
 * Cocos 3.8 的 native.fileUtils／native.AssetsManager checkUpdate
 *
 * projectManifest 要在編輯器把遊戲自己的 .manifest 拖進去，作為內建基準版本。
 * 與 DDPK minigame 相同，每款遊戲使用自己的 writable cache 與 manifest。
 */
@ccclass('1003/NativeBundleUpdater')
export class NativeBundleUpdater extends Component {
    public projectManifest: Asset = null!;

    /** 下載進度 0 到 1 呼叫方接上進度條 */
    public onProgress: ((percent: number) => void) | null = null;

    private updateManager: native.AssetsManager | null = null;

    /**
     * 要更新的 bundle 名稱，跟目前的遊戲代號一致。
     *
     * @returns bundle 名稱。
     */
    private get bundleName(): string {
        return GameConfigManager.GAMEID;
    }

    /**
     * 這個 bundle 熱更檔案的寫入目錄。
     *
     * @returns 可寫目錄下的絕對路徑。
     */
    private get resourceDir(): string {
        return `${native.fileUtils.getWritablePath()}${this.bundleName}_update/`;
    }

    /**
     * App 啟動最早期（在 restoreSearchPaths 之前）針對每個熱更用的 bundle 呼叫
     * native.AssetsManager 下載時內部自己會用 `<resourceDir>_temp/` 當暫存目錄
     * 正常情況更新完成時引擎自己會把暫存內容搬進正式目錄 但如果 App 剛好
     * 在下載完成、搬移完成之間被系統或使用者殺掉
     * native/jsb-default/main.js 開機檢查
     * project.manifest.temp 這個檔案還在的話代表上次真的下載到一半 不要動
     */
    public static finishInterruptedUpdate(bundleName: string): void {
        const resourceDir = `${native.fileUtils.getWritablePath()}${bundleName}_update/`;
        const tempDir = `${resourceDir}_temp/`;
        if (!native.fileUtils.isDirectoryExist(tempDir)) return;
        if (native.fileUtils.isFileExist(`${tempDir}project.manifest.temp`)) return;

        const files: string[] = [];
        native.fileUtils.listFilesRecursively(tempDir, files);
        for (const srcPath of files) {
            const relativePath = srcPath.substring(tempDir.length);
            const dstPath = resourceDir + relativePath;
            if (srcPath.endsWith('/')) {
                native.fileUtils.createDirectory(dstPath);
            } else {
                if (native.fileUtils.isFileExist(dstPath)) {
                    native.fileUtils.removeFile(dstPath);
                }
                native.fileUtils.renameFile(srcPath, dstPath);
            }
        }
        native.fileUtils.removeDirectory(tempDir);
    }

    /**
     * 檢查並在需要時下載更新 沒有新版本會直接 resolve UpToDate
     * 更新完成會呼叫 game.restart 並 resolve Restarting 但 restart
     * 之後這個 scene 的後續程式碼不會再被執行到 呼叫方不用等這個 resolve
     * 做事 真正接續流程在重啟後的 PendingGameEntry 資料
     */
    public async checkAndUpdate(cdnBase?: string): Promise<NativeUpdateResult> {
        const runtimeBase = this.resolveCdnBase(cdnBase);
        console.log(`[NativeBundleUpdater] ${this.bundleName} cdnBase=${runtimeBase}`);
        this.prepareLocalManifests(runtimeBase);

        const localManifestPath = `${this.resourceDir}project.manifest`;
        this.updateManager = new native.AssetsManager(localManifestPath, this.resourceDir, compareVersion);

        const remoteManifest = await this.fetchRemoteManifest(runtimeBase);
        const localVersion = this.updateManager.getLocalManifest().getVersion();
        const remoteVersion = remoteManifest.getVersion();
        console.log(`[NativeBundleUpdater] ${this.bundleName} 本機版本=${localVersion} 遠端版本=${remoteVersion}`);

        if (compareVersion(localVersion, remoteVersion) >= 0) {
            console.log(`[NativeBundleUpdater] ${this.bundleName} 已是最新版本 不下載`);
            return NativeUpdateResult.UpToDate;
        }

        if (!this.updateManager.loadRemoteManifest(remoteManifest)) {
            throw new Error('載入遠端 project.manifest 失敗');
        }

        console.log(`[NativeBundleUpdater] ${this.bundleName} 發現新版本 開始下載`);
        return await new Promise((resolve, reject) => {
            this.updateManager!.setEventCallback((event) => this.onUpdateEvent(event, resolve, reject));
            this.updateManager!.update();
        });
    }

    /**
     * 決定要從哪個 CDN 位址抓更新檔。
     *
     * 優先用傳進來的值，其次用大廳寫進 `__subGameData__` 的那份（且 gameId 要對得上）。
     * 原生環境沒有 `URL` 可用，所以用字串判斷協定而不是 `new URL()`。
     *
     * @param cdnBase 指定的 CDN 位址；省略時走 runtime 設定。
     * @returns 正規化後的 CDN 位址。
     * @throws 兩邊都沒有值時丟出。
     */
    private resolveCdnBase(cdnBase?: string): string {
        const data = getSubGameData();
        const value = cdnBase ?? (data?.gameId === this.bundleName ? data.cdnBase : undefined);
        if (!value) throw new Error(`[NativeBundleUpdater] ${this.bundleName} 缺少 runtime cdnBase`);

        // 原生的 URL 會是 undefined 直接用字串判斷
        if (!/^https?:\/\//i.test(value)) {
            throw new Error('[NativeBundleUpdater] cdnBase 只允許 HTTP(S)');
        }
        return value.replace(/\/+$/, '');
    }

    /**
     * 建立寫入目錄，並把內建的 manifest 複製一份到可寫區當本地版本。
     *
     * @param cdnBase CDN 位址，會寫進 manifest 的遠端欄位。
     */
    private prepareLocalManifests(cdnBase: string): void {
        if (!native.fileUtils.isDirectoryExist(this.resourceDir)) {
            native.fileUtils.createDirectory(this.resourceDir);
        }
        const localManifestPath = `${this.resourceDir}project.manifest`;
        const projectSource = native.fileUtils.isFileExist(localManifestPath)
            ? native.fileUtils.getStringFromFile(localManifestPath)
            : native.fileUtils.getStringFromFile(this.projectManifest.nativeUrl);

        native.fileUtils.writeStringToFile(this.rewriteManifest(projectSource, cdnBase), localManifestPath);
    }

    /**
     * 下載遠端 manifest。
     *
     * 網址帶 `?t=` 時間戳並用 `no-store`，是為了繞過 CDN 邊緣快取——
     * 邊緣節點手上的舊副本可能已經好幾小時了（見 agent-pitfalls.md 坑 #29）。
     *
     * @param cdnBase CDN 位址。
     * @returns 解析後的 manifest。
     * @throws HTTP 非 2xx 時丟出。
     */
    private async fetchRemoteManifest(cdnBase: string): Promise<native.Manifest> {
        const manifestUrl = `${this.remoteBase(cdnBase)}project.manifest?t=${Date.now()}`;
        const response = await fetch(manifestUrl, { cache: 'no-store' });
        if (!response.ok) throw new Error(`下載 project.manifest 失敗 HTTP ${response.status}`);

        const content = this.rewriteManifest(await response.text(), cdnBase);
        const manifest = new native.Manifest(content, this.resourceDir);
        if (!manifest.isLoaded()) throw new Error('遠端 project.manifest 格式錯誤');
        return manifest;
    }

    // 每個平台各自一份 manifest 與版本目錄 不然 android 發布會蓋掉 ios
    /**
     * 依平台組出遠端熱更目錄的網址。
     *
     * @param cdnBase CDN 位址。
     * @returns 帶結尾斜線的目錄網址。
     */
    private remoteBase(cdnBase: string): string {
        const platform = sys.os === sys.OS.ANDROID ? 'android' : 'ios';
        return `${cdnBase}/remote/${this.bundleName}/hotupdate/${platform}/`;
    }

    /**
     * 把 manifest 裡的遠端位址改寫成這次要用的 CDN。
     *
     * 順便驗一次 version 格式：格式錯的 manifest 會讓 AssetsManager 的比對無聲失敗，
     * 寧可在這裡丟例外也不要讓它安靜地判定成「已是最新版」。
     *
     * @param content manifest 的原始內容。
     * @param cdnBase CDN 位址。
     * @returns 改寫後的內容。
     * @throws version 格式不是數字加點時丟出。
     */
    private rewriteManifest(content: string, cdnBase: string): string {
        const manifest = JSON.parse(content) as Record<string, unknown>;
        const version = String(manifest.version ?? '');
        if (!/^\d+(?:\.\d+)*$/.test(version)) {
            throw new Error(`manifest version 格式錯誤: ${version}`);
        }

        const stableBase = this.remoteBase(cdnBase);
        manifest.packageUrl = `${stableBase}${version}/${this.bundleName}/`;
        manifest.remoteManifestUrl = `${stableBase}project.manifest`;
        manifest.remoteVersionUrl = `${stableBase}version.manifest`;
        return JSON.stringify(manifest);
    }

    /**
     * 處理原生更新進度與終止事件，整批完成後才清理舊檔並重啟。
     *
     * @param event - AssetsManager 發出的更新事件。
     * @param resolve - 無更新或準備重啟時回報更新結果的回呼。
     * @param reject - 整批更新或套用失敗時回報錯誤的回呼。
     */
    private onUpdateEvent(
        event: native.EventAssetsManager,
        resolve: (r: NativeUpdateResult) => void,
        reject: (e: Error) => void
    ): void {
        const code = event.getEventCode();
        switch (code) {
            case native.EventAssetsManager.UPDATE_PROGRESSION:
                this.onProgress?.(event.getPercent());
                break;
            case native.EventAssetsManager.ALREADY_UP_TO_DATE:
                this.updateManager?.setEventCallback(null);
                resolve(NativeUpdateResult.UpToDate);
                break;
            case native.EventAssetsManager.UPDATE_FINISHED:
                this.updateManager?.setEventCallback(null);
                try {
                    this.applyUpdateAndRestart(resolve);
                } catch (error) {
                    reject(error instanceof Error ? error : new Error(String(error)));
                }
                break;
            case native.EventAssetsManager.ERROR_NO_LOCAL_MANIFEST:
            case native.EventAssetsManager.ERROR_DOWNLOAD_MANIFEST:
            case native.EventAssetsManager.ERROR_PARSE_MANIFEST:
            case native.EventAssetsManager.UPDATE_FAILED:
                this.updateManager?.setEventCallback(null);
                console.warn(`[NativeBundleUpdater] ${this.bundleName} 熱更失敗 code=${code} ${event.getMessage()}`);
                reject(new Error(`熱更失敗 code=${code} ${event.getMessage()}`));
                break;
            case native.EventAssetsManager.ERROR_UPDATING:
            case native.EventAssetsManager.ERROR_DECOMPRESS:
                // 單一資產錯誤不代表整批停止；等 UPDATE_FAILED 才結束，避免背景仍下載卻進入遊戲。
                console.warn(`[NativeBundleUpdater] 資產更新失敗 ${event.getMessage()}`);
                break;
        }
    }

    /**
     * 清理已完成更新的舊產物，保存並套用搜尋路徑，再重啟遊戲。
     *
     * @param resolve - 重啟前回報 `Restarting` 結果的回呼。
     * @throws 清理舊產物、保存狀態或套用搜尋路徑失敗時拋出錯誤。
     */
    private applyUpdateAndRestart(resolve: (r: NativeUpdateResult) => void): void {
        console.log(`[NativeBundleUpdater] ${this.bundleName} 下載完成 準備套用並重啟`);
        cleanNativeBundle(
            `${this.resourceDir}assets/${this.bundleName}/`,
            this.updateManager!.getLocalManifest().getVersion()
        );
        const searchPaths = native.fileUtils.getSearchPaths();
        const newPaths = this.updateManager!.getLocalManifest().getSearchPaths();
        // 重裝 App 後 container 換新 舊的絕對路徑會失效 卻一路疊下去
        // 相對路徑是引擎內建的空字串會讓 isDirectoryExist 失敗只檢查絕對路徑
        const alive = searchPaths.filter((path) => !path.startsWith('/') || native.fileUtils.isDirectoryExist(path));
        const merged = [...newPaths, this.resourceDir, ...alive].filter(
            (path, index, all) => all.indexOf(path) === index
        );
        // 存起來給下次真正冷啟動（不是走這次的 game.restart()）時還原
        // native.fileUtils 是不是真的能撐過 game.restart() 沒有把握 兩邊都做保險
        sys.localStorage.setItem(SEARCH_PATHS_STORAGE_KEY, JSON.stringify(merged));
        native.fileUtils.setSearchPaths(merged);
        console.log(`[NativeBundleUpdater] ${this.bundleName} searchPaths=${JSON.stringify(merged)}`);
        resolve(NativeUpdateResult.Restarting);
        game.restart();
    }
}

/**
 * 依成功解壓的同版本檔案清單清理舊產物，刪除前先確認清單內的新版檔案全部存在。
 * 缺少清單或清單版本不符時保留現有檔案，避免使用舊清單誤刪。
 *
 * @param root - 子遊戲 Bundle 的絕對目錄，必須以 `/` 結尾。
 * @param version - 已完成更新的本機 manifest 版本。
 * @throws 清單無法解析、格式或路徑無效、新版檔案缺失，或舊檔刪除失敗時拋出錯誤。
 */
function cleanNativeBundle(root: string, version: string): void {
    const files = native.fileUtils;
    // 不能用 . 開頭 導致清單搬不到裝置上
    const inventoryPath = `${root}native-files.json`;
    if (!files.isFileExist(inventoryPath)) {
        console.warn('[NativeUpdate] 舊格式更新包沒有檔案清單，保留舊檔以免誤刪');
        return;
    }
    const inventory = JSON.parse(files.getStringFromFile(inventoryPath));
    if (inventory.version !== version) {
        console.warn('[NativeUpdate] 檔案清單版本不符，不使用舊清單清理新版');
        return;
    }
    if (!Array.isArray(inventory.files) || !inventory.files.length) throw new Error('更新包檔案清單無效');
    const keep = new Set<string>(['native-files.json']);
    for (const name of inventory.files) {
        if (
            typeof name !== 'string' ||
            !name ||
            name.includes('\\') ||
            name.split('/').some((p) => !p || p === '.' || p === '..')
        ) {
            throw new Error('更新包檔案路徑無效');
        }
        if (!files.isFileExist(root + name)) throw new Error(`更新包缺少 ${name}`);
        keep.add(name);
    }
    const entries: string[] = [];
    files.listFilesRecursively(root, entries);
    for (const file of entries) {
        if (file.startsWith(root) && !file.endsWith('/') && !keep.has(file.slice(root.length))) {
            if (!files.removeFile(file)) throw new Error(`無法清理舊檔 ${file}`);
        }
    }
}
