export type Disposer = () => void;

/**
 * 集中管理 EventBus、Cocos event
 * `dispose()` 為 idempotent；dispose 後新增的訂閱會立即解除
 */
export class SubscriptionBag {
    private readonly disposers = new Set<Disposer>();
    private disposed = false;

    /** 加入訂閱並回傳可單獨提前解除 */
    add(disposer: Disposer): Disposer {
        if (this.disposed) {
            disposer();
            return () => undefined;
        }

        let active = true;
        const trackedDisposer = () => {
            if (!active) return;
            active = false;
            this.disposers.delete(trackedDisposer);
            disposer();
        };

        this.disposers.add(trackedDisposer);
        return trackedDisposer;
    }

    /**
     * 把袋子裡所有解除函式跑一遍並清空。重複呼叫是安全的。
     *
     * 先複製一份再走訪：解除函式本身可能又往袋子裡加東西（或移除），
     * 直接走訪原集合會在迭代途中被改動。
     *
     * **每個解除函式各自隔離。** 之前是裸的迴圈，任何一個丟例外就會中止整輪，而這時
     * `disposers` 已經清空、`disposed` 也已經是 true，後面那些訂閱就永遠解不掉也再也
     * 碰不到了。實際踩到的是離開遊戲時 `TemplateView` 對已銷毀的按鈕節點呼叫
     * `Node.off()`（見 agent-pitfalls.md 坑 #44）：一個按鈕的錯誤讓 ViewModel 掛的
     * 全部事件總線訂閱留在 bus 上指著已銷毀的元件。解除本身是收尾動作，單一失敗不該
     * 連坐其餘。
     */
    dispose(): void {
        if (this.disposed) return;
        this.disposed = true;

        const pending = Array.from(this.disposers);
        this.disposers.clear();
        for (const disposer of pending) {
            try {
                disposer();
            } catch (error) {
                console.warn('[SubscriptionBag] 解除訂閱失敗，繼續處理其餘', error);
            }
        }
    }

    /**
     * 這個袋子是否已經清掉過。
     *
     * @returns 已清掉時 true。
     */
    get isDisposed(): boolean {
        return this.disposed;
    }

    /**
     * 目前還掛著幾個解除函式。
     *
     * @returns 數量。
     */
    get size(): number {
        return this.disposers.size;
    }
}
