import { _decorator, Component, Layout, Node, sp, UITransform, Vec3 } from 'cc';
import { BaseToggle } from './BaseToggle';
import { BaseToggleGroup } from './BaseToggleGroup';

const { ccclass, property } = _decorator;

/**
 * 主遊戲的階梯倍數（GDD 4.1）：第一輪 x1，該輪有贏獎就讓下一輪升一階，
 * 走到 x5 之後維持 x5；單局結束重置回 x1。
 */
const NG_LADDER: readonly number[] = [1, 2, 3, 5];

/**
 * 免費遊戲的階梯倍數（GDD 4.3）：整張表換成這四階，每局旋轉從 x2 起算，
 * 連續消除最高到 x10。
 */
const FG_LADDER: readonly number[] = [2, 4, 6, 10];


/**
 * 捲軸上方的階梯倍數面板。
 *
 * 節點結構是七顆固定的階（`x1`／`x2`／`x3`／`x4`／`x5`／`x6`／`x10`），剛好是主遊戲與
 * 免費遊戲兩張表的聯集；每種模式只顯示自己那四階，其餘關掉讓 `cc.Layout` 重新排開。
 * 每顆階都是一個 `BaseToggle`（ON／OFF 兩張圖），互斥選取交給父節點的 `BaseToggleGroup`。
 *
 * **這支只負責顯示，不自己算升階。**倍數由伺服器／mock 逐 step 給值
 * （`SlotApiStep.Mult` → `SlotRoundStep.multiplier`），呼叫端拿到什麼就顯示什麼。
 * mock 引擎 `net/mocks/mahjong-ways.ts` 另有一份同樣的階梯表，那份負責算分、這份負責顯示，
 * 兩邊刻意不互相 import——顯示層不該依賴假資料引擎。
 *
 * 只有橫版 `GameViewH` 有這個節點，直版沒有，所以呼叫端要允許它是 null。
 *
 * 各階實際掛在哪一層由 {@link rungsRoot} 決定：本節點自己帶 `cc.Layout` 就是自己，
 * 否則取第一個帶 `cc.Layout` 的子節點。prefab 把階包進子節點排版時不必改這支。
 */
@ccclass('1003/TimesController')
export class TimesController extends Component {
    @property({
        type: sp.Skeleton,
        displayName: '升階演出',
        tooltip: '留空時自動找名為 ui_mul 的子節點',
    })
    stepSpine: sp.Skeleton = null!;

    private group: BaseToggleGroup | null = null;

    private layout: Layout | null = null;

    /** 各階實際掛載的節點；本節點沒有 cc.Layout 時是帶 Layout 的那個子節點 */
    private rungsRoot: Node = null!;

    /** 倍數 → 那一階的 BaseToggle */
    private readonly rungs = new Map<number, BaseToggle>();

    /** 初始化跑完了沒；在那之前對外呼叫只記錄狀態，不動畫面 */
    private ready = false;

    private isFree = false;

    /** 目前點亮的倍數；0 代表還沒套用過任何一階 */
    private current = 0;

    private warnedMissingValue = false;

    /**
     * 目前模式對應的階梯表。
     *
     * @returns 免費遊戲回 `FG_LADDER`，主遊戲回 `NG_LADDER`。
     */
    private get ladder(): readonly number[] {
        return this.isFree ? FG_LADDER : NG_LADDER;
    }

    /**
     * 取得同節點的群組與 Layout，並依名稱收集七顆階。
     */
    protected override onLoad(): void {
        this.resolveRungsRoot();
        this.resolveGroup();
        this.resolveStepSpine();
        this.collectRungs();
    }

    /**
     * 找互斥群組。
     *
     * 先看 {@link rungsRoot}，再退回本節點——`BaseToggleGroup` 只收直屬子節點上的 Toggle，
     * 所以它該跟各階待在同一層；但舊結構是整組都掛在本節點上，兩種都要認得。
     */
    private resolveGroup(): void {
        this.group = this.rungsRoot.getComponent(BaseToggleGroup) ?? this.getComponent(BaseToggleGroup);
        if (!this.group) {
            console.warn(`[TimesController] ${this.rungsRoot.name} 與本節點都沒有 BaseToggleGroup，階梯倍數不會顯示`);
        }
    }

    /**
     * 決定各階掛在哪一層。
     *
     * 本節點自己帶 `cc.Layout` 就是自己；否則取第一個帶 `cc.Layout` 的子節點——prefab 把
     * 七顆階包進一個排版用的子節點時走這條。兩種都沒有就退回本節點，並留一行 warn。
     */
    private resolveRungsRoot(): void {
        const own = this.getComponent(Layout);
        if (own) {
            this.rungsRoot = this.node;
            this.layout = own;
            return;
        }

        for (const child of this.node.children) {
            const layout = child.getComponent(Layout);
            if (!layout) continue;
            this.rungsRoot = child;
            this.layout = layout;
            return;
        }

        this.rungsRoot = this.node;
        this.layout = null;
        console.warn('[TimesController] 本節點與子節點都沒有 cc.Layout，階梯不會重新排開');
    }

    /**
     * 取升階演出用的 spine。`stepSpine` 沒接時自動找名為 `ui_mul` 的子節點。
     */
    private resolveStepSpine(): void {
        if (this.stepSpine) return;
        this.stepSpine = this.node.getChildByName('ui_mul')?.getComponent(sp.Skeleton) ?? null!;
    }

    /**
     * 套用初始狀態。
     *
     * 放在 `start()` 而不是 `onLoad()`：Cocos 會把整棵樹的 `onLoad` 跑完才進 start 階段，
     * 所以此時各階的 `BaseToggle` 都已經註冊進群組、`TOUCH_END` 也掛好了，`cc.Layout`
     * 自己的初始化同樣跑完，`updateLayout()` 排得動。
     */
    protected override start(): void {
        this.detachToggleClicks();
        this.stopDefaultSpine();
        this.ready = true;
        if (this.current === 0) this.current = this.ladder[0];
        this.applyVisibleRungs();
        this.applySelection();
        this.syncSpineToCurrent(true);
    }

    /**
     * 切換主遊戲／免費遊戲的階梯表，並回到該模式的第一階。
     *
     * @param isFree true = 免費遊戲（x2／x4／x6／x10），false = 主遊戲（x1／x2／x3／x5）。
     */
    public setMode(isFree: boolean): void {
        this.isFree = isFree;
        this.current = this.ladder[0];
        if (!this.ready) return;
        this.applyVisibleRungs();
        this.applySelection();

        if (isFree) {
            // levelup 是整面階梯換表的演出，不屬於任何一階，播在面板原點。
            // 座標固定就不必等 Layout 重排，可以當下播。
            this.moveSpineToOrigin();
            this.playSpine('levelup');
            return;
        }

        // 回主遊戲只把演出搬到第一階，不播。換了階梯表要等版面重排完才知道第一階在哪，
        // 所以延後一幀
        this.syncSpineToCurrent(true);
    }

    /**
     * 點亮指定倍數那一階。
     *
     * @param value 這個 step 的階梯倍數，來自伺服器／mock 的 `Mult`。
     *              不在目前模式的階梯表裡時只印一次 warn 並維持現狀，不改畫面。
     *              是目前模式的起始階時只搬位置、不播演出——那一階不是升上來的。
     */
    public showMultiplier(value: number): void {
        if (!this.ladder.includes(value)) {
            if (!this.warnedMissingValue) {
                this.warnedMissingValue = true;
                const mode = this.isFree ? '免費遊戲' : '主遊戲';
                const expected = this.ladder.map((v) => `x${v}`).join('／');
                console.warn(`[TimesController] ${mode}的階梯表沒有 x${value}（預期 ${expected}），維持現狀`);
            }
            return;
        }

        this.current = value;
        if (!this.ready) return;
        this.applySelection();
        // 起始階（主遊戲 x1、免費遊戲 x2）不是升上來的，只搬位置不播演出
        const isBaseRung = value === this.ladder[0];
        this.syncSpineToCurrent(false, isBaseRung ? undefined : 'begin');
    }

    /**
     * 目前點亮那一階的節點。
     *
     * 給倍率飛行特效當起點用（見 `MultiplierFlyEffect.playMultiplierFly()`）。只讀不寫——
     * 要改顯示一律走 {@link showMultiplier}，不要讓外面直接動這顆節點。
     *
     * @returns 那一階的節點；`start()` 還沒跑完、或這一階不在目前模式的階梯表裡時是 null。
     */
    public get currentRungNode(): Node | null {
        if (!this.ready) return null;

        const node = this.rungs.get(this.current)?.node ?? null;

        return node?.isValid ? node : null;
    }

    /**
     * 回到目前模式的第一階（主遊戲 x1、免費遊戲 x2）。
     *
     * 對應 GDD 4.1「結算總贏分並將倍數重置為 x1」與測試清單第 5 項。
     */
    public reset(): void {
        this.current = this.ladder[0];
        if (!this.ready) return;
        this.applySelection();
        // 退回第一階也要把演出搬回去，但這不是升階，不播動畫
        this.syncSpineToCurrent(false);
    }

    /**
     * 依名稱 `x<倍數>` 收集 {@link rungsRoot} 底下的 BaseToggle，並補登記進群組。
     *
     * 順手用群組公開的 `register()` 補登記一次。群組跟各階同層時它自己的 `onLoad` 早就收過了，
     * 這裡是去重後的 no-op；但群組若被放在別層（例如整組掛在本節點、各階包在排版子節點裡），
     * 它的直屬子節點掃描會收不到，`selectToggle()` 查不到索引就直接返回、一顆都不會亮。
     * 補這一行讓兩種擺法都成立。
     */
    private collectRungs(): void {
        for (const child of this.rungsRoot.children) {
            const toggle = child.getComponent(BaseToggle);
            if (!toggle) continue;

            const value = Number(child.name.replace(/^x/, ''));
            if (Number.isFinite(value)) this.rungs.set(value, toggle);
            this.group?.register(toggle);
        }

        const expected = Array.from(new Set([...NG_LADDER, ...FG_LADDER]));
        const missing = expected.filter((value) => !this.rungs.has(value));
        if (missing.length > 0) {
            const names = missing.map((v) => `x${v}`).join('、');
            console.warn(`[TimesController] 在 ${this.rungsRoot.name} 底下找不到階梯節點：${names}（節點名稱要叫 x1、x2…）`);
        }
    }

    /**
     * 拿掉每顆階的點擊監聽。
     *
     * 階梯倍數是演出狀態，不是玩家可以選的項目——`BaseToggle` 在 `onLoad` 一律會掛上
     * `TOUCH_END`，留著的話玩家戳一下就會改變顯示，再戳一次還會整組熄掉
     * （agent-pitfalls.md 坑 #8）。所以初始化時把它解掉。
     */
    private detachToggleClicks(): void {
        for (const toggle of this.rungs.values()) {
            toggle.node.off(Node.EventType.TOUCH_END);
        }
    }

    /**
     * 只顯示目前模式那四階，其餘關掉，並讓 Layout 重新排開。
     */
    private applyVisibleRungs(): void {
        for (const [value, toggle] of this.rungs) {
            toggle.node.active = this.ladder.includes(value);
        }
        this.layout?.updateLayout(true);
    }

    /**
     * 點亮 `current` 那一階。
     *
     * 只管 toggle，升階演出由各呼叫端自己決定要不要搬、要不要播——藏在這裡的話
     * `reset()` 每局都會放一次 `begin`。
     *
     * 交給 `BaseToggleGroup.selectToggle()` 處理互斥。不用理會群組的 `defaultIndex`——
     * 它的 `start()` 認得「已經有人明確選過」就不會覆蓋，見 BaseToggleGroup 檔頭。
     */
    private applySelection(): void {
        const toggle = this.rungs.get(this.current);
        if (!toggle || !this.group) return;

        this.group.selectToggle(toggle);
    }

    /**
     * 把升階演出搬到目前點亮那一階的位置，需要的話再播一段動畫。
     *
     * spine 掛在本節點底下，階卻可能在 {@link rungsRoot} 這個子節點裡，兩者差一層，
     * 所以走世界座標轉回本節點的區域座標，不管中間隔幾層都對。
     *
     * @param deferred 是否延後一幀。版面剛被 `applyVisibleRungs()` 重排過時要開——
     *                 `cc.Layout` 同一幀還沒把各階挪到新位置，當下讀到的是舊座標。
     * @param animation 要播的動畫名；不給就只移動不播。
     */
    private syncSpineToCurrent(deferred: boolean, animation?: string): void {
        const move = (): void => {
            const toggle = this.rungs.get(this.current);
            if (!toggle || !this.stepSpine?.node?.isValid) return;

            const space = this.node.getComponent(UITransform);
            if (!space) return;

            const world = toggle.node.getWorldPosition();
            const local = space.convertToNodeSpaceAR(world, new Vec3());
            this.stepSpine.node.setPosition(local);

            if (animation) this.playSpine(animation);
        };

        if (deferred) this.scheduleOnce(move, 0);
        else move();
    }

    /**
     * 把升階演出停在設定姿勢。
     *
     * prefab 上的 `defaultAnimation` 會在節點啟用時自動播，`loop` 開著就一直循環。
     * 這支既然負責決定播放時機（進 FG 播 `levelup`、升階播 `begin`），就先把軌道清掉，
     * 否則還沒進 FG 就會看到 `levelup` 一直跑。
     */
    private stopDefaultSpine(): void {
        if (!this.stepSpine?.node?.isValid) return;
        this.stepSpine.clearTrack(0);
        this.stepSpine.setToSetupPose();
    }

    /**
     * 把升階演出搬回面板原點。播 `levelup` 用——那段不是針對某一階的效果。
     */
    private moveSpineToOrigin(): void {
        if (!this.stepSpine?.node?.isValid) return;
        this.stepSpine.node.setPosition(0, 0, 0);
    }

    /**
     * 播一段升階演出；spine 沒接就靜靜跳過。
     *
     * @param animation 動畫名稱，目前只有 `begin` 與 `levelup` 兩種。
     */
    private playSpine(animation: string): void {
        if (!this.stepSpine?.node?.isValid) return;
        this.stepSpine.setAnimation(0, animation, false);
    }
}
